import type { ComponentProps, ReactNode } from "react";
import { cn } from "@/lib/utils";

export type TableToolbarProps = Omit<ComponentProps<"div">, "title"> & {
  title?: ReactNode;
  titleId?: string;
  description?: ReactNode;
  descriptionId?: string;
  count?: ReactNode;
  search?: ReactNode;
  actions?: ReactNode;
  selection?: ReactNode;
};

export function TableToolbar({
  title,
  titleId,
  description,
  descriptionId,
  count,
  search,
  actions,
  selection,
  children,
  className,
  ...props
}: TableToolbarProps) {
  return (
    <div
      data-slot="table-toolbar"
      className={cn(
        "grid gap-4 border-b border-border px-4 py-4 sm:px-6",
        className,
      )}
      {...props}
    >
      {(title || description) && (
        <div className="min-w-0">
          {title && (
            <div className="flex flex-wrap items-center gap-2.5">
              <h2
                id={titleId}
                className="text-base leading-6 font-semibold tracking-tight"
              >
                {title}
              </h2>
              {count != null && (
                <span className="rounded-full border border-primary/20 bg-accent/65 px-2.5 py-0.5 text-xs font-medium text-foreground tabular-nums">
                  {count}
                </span>
              )}
            </div>
          )}
          {description && (
            <p
              id={descriptionId}
              className="mt-1 text-[13px] leading-6 text-muted-foreground"
            >
              {description}
            </p>
          )}
        </div>
      )}
      {(search || actions || children) && (
        <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          {search}
          {(actions || children) && (
            <div
              data-slot="table-toolbar-actions"
              className="flex flex-wrap items-center gap-2 sm:ml-auto"
            >
              {actions}
              {children}
            </div>
          )}
        </div>
      )}
      {selection && (
        <div
          data-slot="table-selection-toolbar"
          className="flex flex-wrap items-center justify-between gap-3 rounded-[var(--radius-md,10px)] border border-primary/20 bg-accent/50 px-3 py-2.5"
        >
          {selection}
        </div>
      )}
    </div>
  );
}

import type {
  IntegrationAction,
  IntegrationRecord,
  IntegrationUpdate,
  IntegrationValues,
} from "../../lib/integrations/contracts";

export type ProductCollaborationScope = {
  resourceId: string;
  workspaceId: string;
  connectionId: string;
  integrationId: string;
};

export type ProductReplyTarget = {
  resourceId: string;
  threadId: string;
  parentId: string;
};

export type ProductReportedMessage = {
  record: IntegrationRecord;
  threadId?: string;
  parentId?: string;
  parent?: IntegrationRecord;
  relation: "flat" | "root" | "reply" | "parent-unavailable" | "invalid";
  replyTarget?: ProductReplyTarget;
};

export type ProductReportedConversation = {
  resourceId: string;
  messages: ProductReportedMessage[];
  flat: ProductReportedMessage[];
  threads: { id: string; messages: ProductReportedMessage[] }[];
};

const messageTypes = new Set(["message", "chat", "comment"]);

function reportedText(value: unknown, maximum: number) {
  return typeof value === "string" &&
    value.length <= maximum &&
    value.trim().length > 0 &&
    !/[\u0000-\u001f\u007f]/.test(value)
    ? value
    : undefined;
}

function reportedId(value: unknown) {
  return reportedText(value, 200);
}

/** Local assets/proxy paths or HTTPS images; no credentials or alternate schemes. */
export function productPresenceAvatarUrl(value: unknown) {
  if (
    typeof value !== "string" ||
    !value ||
    value.length > 8192 ||
    value !== value.trim() ||
    /[\\\u0000-\u001f\u007f]/.test(value)
  )
    return undefined;
  if (value.startsWith("/")) return value.startsWith("//") ? undefined : value;
  try {
    const url = new URL(value);
    return url.protocol === "https:" && !url.username && !url.password
      ? url.href
      : undefined;
  } catch {
    return undefined;
  }
}

/** Presence is a server snapshot, including an empty snapshot; never seed people. */
export function productPresenceRecords(
  members: Extract<IntegrationUpdate, { kind: "presence" }>["members"],
): IntegrationRecord[] {
  const seen = new Set<string>();
  return members.slice(0, 1000).flatMap((member) => {
    const id = reportedId(member.id);
    const name = reportedText(member.name, 160);
    if (!id || !name || seen.has(id)) return [];
    seen.add(id);
    const avatarUrl = productPresenceAvatarUrl(member.avatarUrl);
    return [
      {
        id,
        name,
        type: "presence",
        status: member.state,
        description: "",
        updatedAt: "",
        ...(avatarUrl ? { fields: { avatarUrl } } : {}),
      },
    ];
  });
}

/** Join an author to presence by an explicit ID, never by a guessed display name. */
export function productCollaborationAuthor(
  record: IntegrationRecord,
  presence: readonly IntegrationRecord[],
) {
  const id = reportedId(record.fields?.authorId);
  const matching = id ? presence.filter((member) => member.id === id) : [];
  const member = matching.length === 1 ? matching[0] : undefined;
  return {
    id,
    name:
      reportedText(record.fields?.authorName, 160) ??
      reportedText(member?.name, 160),
    avatarUrl: member
      ? productPresenceAvatarUrl(member.fields?.avatarUrl)
      : undefined,
  };
}

/**
 * Query/room-specific subscriptions may omit redundant room fields. A connection
 * stream must report a resource before its records can enter a selected room.
 */
export function productCollaborationRecords(
  records: readonly IntegrationRecord[],
  scope: ProductCollaborationScope,
  requireResource = false,
) {
  return records.filter((record) => {
    const fields = record.fields ?? {};
    const bindings = ["resourceId", "roomId", "channelId"];
    if (
      requireResource &&
      !bindings.some((key) => reportedId(fields[key]) !== undefined)
    )
      return false;
    return (
      bindings.every(
        (key) =>
          fields[key] === undefined ||
          fields[key] === "" ||
          fields[key] === scope.resourceId,
      ) &&
      ["workspaceId", "connectionId", "integrationId"].every(
        (key) =>
          fields[key] === undefined ||
          fields[key] === scope[key as keyof ProductCollaborationScope],
      )
    );
  });
}

/**
 * Bounded, flat projection. Only reported thread IDs create groups; a reply label
 * requires a loaded parent in that same group. Missing history stays visible.
 */
export function productReportedConversation(
  records: readonly IntegrationRecord[],
  scope: ProductCollaborationScope,
): ProductReportedConversation {
  const loaded = productCollaborationRecords(records.slice(-100), scope).filter(
    (record) => messageTypes.has(record.type),
  );
  const counts = new Map<string, number>();
  for (const record of loaded)
    counts.set(record.id, (counts.get(record.id) ?? 0) + 1);
  const messages: ProductReportedMessage[] = loaded.map((record) => {
    const threadId = reportedId(record.fields?.threadId);
    const parentId = reportedId(record.fields?.parentId);
    const invalidParent =
      record.fields?.parentId !== undefined &&
      record.fields.parentId !== "" &&
      !parentId;
    if (!reportedId(record.id) || counts.get(record.id) !== 1 || invalidParent)
      return { record, relation: "invalid" };
    if (!threadId) return { record, relation: "flat" };
    return {
      record,
      threadId,
      parentId,
      relation: parentId ? "parent-unavailable" : "root",
    };
  });
  const byId = new Map(
    messages
      .filter((message) => counts.get(message.record.id) === 1)
      .map((message) => [message.record.id, message]),
  );
  const groups = new Map<string, ProductReportedMessage[]>();
  for (const message of messages) {
    if (!message.threadId) continue;
    if (message.parentId) {
      const parent = byId.get(message.parentId);
      if (parent) {
        if (
          parent === message ||
          parent.threadId !== message.threadId ||
          parent.relation === "invalid"
        )
          message.relation = "invalid";
        else {
          message.parent = parent.record;
          message.relation = "reply";
        }
      }
    }
    // No recursive rendering or inferred roots, including cyclic provider data.
    const visited = new Set<string>([message.record.id]);
    let ancestor = message.parentId;
    while (ancestor) {
      if (visited.has(ancestor)) {
        message.relation = "invalid";
        message.parent = undefined;
        break;
      }
      visited.add(ancestor);
      const parent = byId.get(ancestor);
      if (!parent || parent.threadId !== message.threadId) break;
      ancestor = parent.parentId;
    }
    if (
      message.relation !== "invalid" &&
      reportedId(scope.resourceId) &&
      !["deleted", "removed", "deleting"].includes(message.record.status)
    )
      message.replyTarget = {
        resourceId: scope.resourceId,
        threadId: message.threadId,
        parentId: message.record.id,
      };
    const group = groups.get(message.threadId) ?? [];
    group.push(message);
    groups.set(message.threadId, group);
  }
  return {
    resourceId: scope.resourceId,
    messages,
    flat: messages.filter((message) => !message.threadId),
    threads: [...groups].map(([id, items]) => ({ id, messages: items })),
  };
}

/** Revalidate at review/confirmation; never downgrade a disappeared reply to a post. */
export function productReplyIsCurrent(
  conversation: ProductReportedConversation,
  target: ProductReplyTarget,
) {
  return (
    conversation.resourceId === target.resourceId &&
    conversation.messages.some(
      (message) =>
        message.replyTarget?.threadId === target.threadId &&
        message.replyTarget.parentId === target.parentId &&
        message.replyTarget.resourceId === target.resourceId,
    )
  );
}

export function productSupportsReplies(action?: IntegrationAction) {
  return (
    action?.kind === "publish-message" &&
    ["threadId", "parentId"].every((id) =>
      action.fields.some((field) => field.id === id && field.type === "text"),
    )
  );
}

/**
 * Build only declared inputs. Room and reply IDs come from the selected context;
 * author identity is supplied by the backend, not editable frontend values.
 */
export function productCollaborationPublishValues({
  action,
  extra,
  message,
  conversation,
  reply,
}: {
  action?: IntegrationAction;
  extra: IntegrationValues;
  message: string;
  conversation: ProductReportedConversation;
  reply: ProductReplyTarget | null;
}): IntegrationValues | undefined {
  if (
    !action ||
    action.kind !== "publish-message" ||
    !reportedId(conversation.resourceId) ||
    (reply &&
      (!productSupportsReplies(action) ||
        !productReplyIsCurrent(conversation, reply)))
  )
    return undefined;
  const values: IntegrationValues = {};
  for (const field of action.fields) {
    if (["threadId", "parentId", "authorId", "authorName"].includes(field.id))
      continue;
    if (["resourceId", "roomId", "channelId"].includes(field.id))
      values[field.id] = conversation.resourceId;
    else if (["message", "content"].includes(field.id))
      values[field.id] = message;
    else
      values[field.id] =
        extra[field.id] ??
        (field.type === "toggle"
          ? false
          : field.type === "select"
            ? (field.options?.[0]?.value ?? "")
            : "");
  }
  if (reply) {
    values.threadId = reply.threadId;
    values.parentId = reply.parentId;
  }
  return values;
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  MessageSquare,
  RefreshCw,
  Reply,
  Save,
  Send,
  Users,
} from "lucide-react";
import { useLanguage } from "@/hooks/use-language";
import { useIntegrationOperation } from "@/hooks/use-integration-operation";
import { Button } from "@/components/ui/button";
import { Avatar } from "@/components/ui/avatar";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { Select } from "@/components/ui/select";
import type {
  IntegrationAction,
  IntegrationDocument,
  IntegrationRecord,
  IntegrationUpdate,
  IntegrationValues,
  IntegrationWorkbenchProps,
} from "@/lib/integrations/contracts";
import type { ProductEditorRenderer } from "./product-document";
import {
  findProductAction,
  invalidProductField,
  mergeProductRecords,
  productActionValues,
  productScopeKey,
} from "./product-model";
import { startProductSubscription } from "./product-subscription";
import {
  productCollaborationAuthor,
  productCollaborationPublishValues,
  productCollaborationRecords,
  productPresenceAvatarUrl,
  productPresenceRecords,
  productReplyIsCurrent,
  productReportedConversation,
  productSupportsReplies,
  type ProductReportedMessage,
  type ProductReplyTarget,
} from "./product-collaboration-model";
import {
  ProductActionUnavailable,
  ProductDate,
  ProductDocumentPreview,
  ProductEmpty,
  ProductFields,
  ProductLabeledTextarea,
  ProductOperationFeedback,
  ProductPanel,
  ProductRecordList,
  ProductResourcePicker,
  ProductResult,
  ProductReview,
  ProductStatus,
  ProductValidation,
  useProductResources,
} from "./product-ui";

export type ProductCollaborationUpdate =
  | IntegrationUpdate
  | { kind: "records"; records: IntegrationRecord[]; cursor?: string }
  | { kind: "presence"; records: IntegrationRecord[] }
  | { kind: "document"; document: IntegrationDocument }
  | { kind: "connection"; state: "connected" | "reconnecting" | "closed" };

export type ProductCollaborationSubscription = {
  integrationId: string;
  connectionId: string;
  workspaceId: string;
  resourceId: string;
  resumeCursor?: string;
  signal: AbortSignal;
  onUpdate: (update: ProductCollaborationUpdate) => void;
  onError: () => void;
};
/** Return a cleanup function; credentials and provider transports stay with the consumer. */
export type ProductCollaborationSubscribe = (
  request: ProductCollaborationSubscription,
) => (() => void) | Promise<() => void>;

export function ProductCollaborationWorkbench(
  props: IntegrationWorkbenchProps & {
    subscribe?: ProductCollaborationSubscribe;
    renderEditor?: ProductEditorRenderer;
  },
) {
  const { l, locale } = useLanguage();
  const read = useIntegrationOperation(props);
  const write = useIntegrationOperation(props);
  const readRun = read.run;
  const readCancel = read.cancel;
  const writeCancel = write.cancel;
  const resources = useProductResources(props);
  const queryAction = findProductAction(props.definition, "query");
  const publishAction = findProductAction(props.definition, "publish-message");
  const saveAction = findProductAction(props.definition, "save-document");
  const checkpointAction = findProductAction(props.definition, "checkpoint");
  const [resourceId, setResourceId] = useState(
    props.connection.resourceIds[0] ?? "",
  );
  const [records, setRecords] = useState<IntegrationRecord[]>([]);
  const [presence, setPresence] = useState<IntegrationRecord[]>([]);
  const [selectedThread, setSelectedThread] = useState("");
  const [reply, setReply] = useState<ProductReplyTarget | null>(null);
  const [message, setMessage] = useState("");
  const messageInput = useRef<HTMLTextAreaElement>(null);
  const [extra, setExtra] = useState<IntegrationValues>({});
  const [base, setBase] = useState<IntegrationDocument | null>(null);
  const [draft, setDraft] = useState("");
  const [draftTitle, setDraftTitle] = useState("");
  const [draftFormat, setDraftFormat] =
    useState<IntegrationDocument["format"]>("markdown");
  const [remote, setRemote] = useState<IntegrationDocument | null>(null);
  const [cursor, setCursor] = useState("");
  const [lastUpdate, setLastUpdate] = useState<string | null>(null);
  const [now, setNow] = useState(0);
  const [follow, setFollow] = useState(false);
  const [streamState, setStreamState] = useState("idle");
  const [streamError, setStreamError] = useState(false);
  const [scopeStale, setScopeStale] = useState(false);
  const [streamEpoch, setStreamEpoch] = useState(0);
  const [review, setReview] = useState<{
    action: IntegrationAction;
    values: IntegrationValues;
    resourceId: string;
    reply?: ProductReplyTarget;
  } | null>(null);
  const [watermark, setWatermark] = useState("");
  const roomScope = useMemo(
    () => ({
      resourceId,
      connectionId: props.connection.id,
      workspaceId: props.scope.workspaceId,
      integrationId: props.definition.id,
    }),
    [
      resourceId,
      props.connection.id,
      props.scope.workspaceId,
      props.definition.id,
    ],
  );
  const conversation = useMemo(
    () => productReportedConversation(records, roomScope),
    [records, roomScope],
  );
  const current = useRef({
    resourceId,
    scopeStale,
    base,
    draft,
    draftTitle,
    draftFormat,
    cursor,
    lastUpdate,
    watermark,
    busy: false,
  });
  useEffect(() => {
    current.current = {
      resourceId,
      scopeStale,
      base,
      draft,
      draftTitle,
      draftFormat,
      cursor,
      lastUpdate,
      watermark,
      busy: read.pending || write.pending,
    };
  }, [
    resourceId,
    scopeStale,
    base,
    draft,
    draftTitle,
    draftFormat,
    cursor,
    lastUpdate,
    watermark,
    read.pending,
    write.pending,
  ]);

  const receive = useCallback(
    (update: ProductCollaborationUpdate, connectionWide = false) => {
      if (
        current.current.scopeStale ||
        current.current.resourceId !== resourceId
      )
        return;
      if (update.kind === "connection") {
        setStreamState(
          "connection" in update
            ? update.connection.status === "connected"
              ? "connected"
              : "closed"
            : update.state,
        );
        return;
      }
      if (update.kind === "result") {
        if (update.result.kind === "records") update = update.result;
        else if (update.result.kind === "record")
          update = { kind: "records", records: [update.result.record] };
        else if (update.result.kind === "document") update = update.result;
        else return;
      }
      if (update.kind === "records") {
        const scoped = productCollaborationRecords(
          update.records,
          roomScope,
          connectionWide,
        );
        if (update.records.length && !scoped.length) return;
        update = { ...update, records: scoped };
      }
      if (update.kind === "presence" && "records" in update) {
        const scoped = productCollaborationRecords(update.records, roomScope);
        if (update.records.length && !scoped.length) return;
        update = { ...update, records: scoped };
      }
      setLastUpdate(new Date().toISOString());
      setStreamState("connected");
      if (update.kind === "presence") {
        if ("members" in update)
          setPresence(productPresenceRecords(update.members));
        else
          setPresence((items) =>
            mergeProductRecords(items, update.records).slice(-1000),
          );
      }
      if (update.kind === "records") {
        setRecords((items) =>
          mergeProductRecords(
            items,
            update.records.filter(
              (record) => !["presence", "participant"].includes(record.type),
            ),
          ).slice(-100),
        );
        setPresence((items) =>
          mergeProductRecords(
            items,
            update.records.filter((record) =>
              ["presence", "participant"].includes(record.type),
            ),
          ).slice(-1000),
        );
        if (update.cursor !== undefined) setCursor(update.cursor);
        const timestamps = update.records
          .map((record) => record.updatedAt)
          .filter((value) => Number.isFinite(Date.parse(value)))
          .sort((a, b) => Date.parse(b) - Date.parse(a));
        if (timestamps[0])
          setWatermark((previous) =>
            !previous || Date.parse(timestamps[0]) > Date.parse(previous)
              ? timestamps[0]
              : previous,
          );
      }
      if (update.kind === "document") {
        const previous = current.current.base;
        if (previous && previous.id !== update.document.id) return;
        if (
          previous?.id === update.document.id &&
          previous.revision > update.document.revision
        )
          return;
        if (
          previous &&
          (current.current.draft !== previous.content ||
            current.current.draftTitle !== previous.title ||
            current.current.draftFormat !== previous.format)
        )
          setRemote(update.document);
        else {
          setBase(update.document);
          setDraft(update.document.content);
          setDraftTitle(update.document.title);
          setDraftFormat(update.document.format);
          current.current.base = update.document;
          current.current.draft = update.document.content;
          current.current.draftTitle = update.document.title;
          current.current.draftFormat = update.document.format;
        }
      }
    },
    [resourceId, roomScope],
  );

  const load = useCallback(
    async (view = "messages") => {
      if (!queryAction || current.current.busy || scopeStale) return;
      const result = await readRun(
        queryAction,
        productActionValues(
          queryAction,
          {
            ...extra,
            view,
            cursor: current.current.cursor,
            since: current.current.watermark,
            documentId: current.current.base?.id || extra.documentId || "",
          },
          resourceId,
        ),
      );
      if (result?.kind === "records") receive(result);
      else if (result?.kind === "document") receive(result);
    },
    [queryAction, readRun, extra, resourceId, receive, scopeStale],
  );

  useEffect(() => {
    const timer = setInterval(() => setNow(Date.now()), 5000);
    setNow(Date.now());
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    if (!follow || props.subscribe || props.adapter.subscribe || scopeStale)
      return;
    void load();
    const timer = setInterval(() => {
      if (document.visibilityState === "visible") void load();
    }, 15_000);
    return () => clearInterval(timer);
  }, [follow, props.subscribe, props.adapter.subscribe, load, scopeStale]);

  useEffect(() => {
    if (
      (!props.subscribe && !props.adapter.subscribe) ||
      !follow ||
      !props.connection.resourceIds.includes(resourceId) ||
      scopeStale
    )
      return;
    setStreamState("connecting");
    setStreamError(false);
    return startProductSubscription<ProductCollaborationUpdate>(
      (listener, signal) => {
        if (props.subscribe)
          return props.subscribe({
            integrationId: props.definition.id,
            connectionId: props.connection.id,
            workspaceId: props.scope.workspaceId,
            resourceId,
            resumeCursor: current.current.cursor || undefined,
            signal,
            onUpdate: listener,
            onError: () => {
              if (!signal.aborted) {
                setStreamError(true);
                setStreamState("reconnecting");
              }
            },
          });
        return props.adapter.subscribe!(props.connection.id, listener, {
          workspaceId: props.scope.workspaceId,
          signal,
        });
      },
      {
        signal: props.scope.signal,
        onUpdate: (update) => {
          if (update.kind === "connection" && "connection" in update) {
            if (
              update.connection.id !== props.connection.id ||
              update.connection.workspaceId !== props.scope.workspaceId ||
              update.connection.integrationId !== props.definition.id
            )
              return;
            if (
              productScopeKey({ ...props, connection: update.connection }) !==
              productScopeKey(props)
            ) {
              current.current.scopeStale = true;
              setScopeStale(true);
              setFollow(false);
              setPresence([]);
              setReply(null);
              setReview(null);
              readCancel();
              writeCancel();
              return;
            }
          }
          receive(update, !props.subscribe);
        },
        onError: () => {
          setStreamError(true);
          setStreamState("reconnecting");
        },
      },
    );
  }, [
    props,
    resourceId,
    receive,
    follow,
    streamEpoch,
    scopeStale,
    readCancel,
    writeCancel,
  ]);

  function stage(
    action: IntegrationAction | undefined,
    values: IntegrationValues,
  ) {
    if (!action || scopeStale || current.current.scopeStale || write.pending)
      return;
    const prepared =
      action.kind === "publish-message"
        ? productCollaborationPublishValues({
            action,
            extra,
            message,
            conversation,
            reply,
          })
        : productActionValues(action, { ...extra, ...values }, resourceId);
    if (prepared && !invalidProductField(action, prepared))
      setReview({
        action,
        values: prepared,
        resourceId,
        ...(action.kind === "publish-message" && reply ? { reply } : {}),
      });
  }
  async function submit() {
    if (
      !review ||
      scopeStale ||
      current.current.scopeStale ||
      review.resourceId !== resourceId ||
      (review.reply && !productReplyIsCurrent(conversation, review.reply))
    )
      return;
    const result = await write.run(review.action, review.values);
    if (!result) return;
    if (result.kind === "record")
      receive({ kind: "records", records: [result.record] });
    if (result.kind === "document") {
      setBase(result.document);
      setDraft(result.document.content);
      setDraftTitle(result.document.title);
      setDraftFormat(result.document.format);
      setRemote(null);
    }
    if (review.action.kind === "publish-message") {
      setMessage("");
      setReply(null);
      setSelectedThread(review.reply?.threadId ?? "");
    }
    setReview(null);
  }
  const stale = lastUpdate && now - Date.parse(lastUpdate) > 45_000;
  const messageValues = productCollaborationPublishValues({
    action: publishAction,
    extra,
    message,
    conversation,
    reply,
  });
  const canPublish =
    !!publishAction &&
    (publishAction.requiredPermissions ?? []).every((id) =>
      props.connection.grantedPermissions.includes(id),
    );
  const canReply = canPublish && productSupportsReplies(publishAction);
  const replyCurrent = !reply || productReplyIsCurrent(conversation, reply);
  const reviewCurrent =
    !review ||
    (review.resourceId === resourceId &&
      (!review.reply || productReplyIsCurrent(conversation, review.reply)));
  const replyMessage = reply
    ? conversation.messages.find(
        (item) =>
          item.record.id === reply.parentId && item.threadId === reply.threadId,
      )
    : undefined;
  const visibleThreads = selectedThread
    ? conversation.threads.filter((thread) => thread.id === selectedThread)
    : conversation.threads;
  const documentValues = productActionValues(
    saveAction,
    {
      ...extra,
      documentId: base?.id ?? "",
      id: base?.id ?? "",
      title: draftTitle,
      content: draft,
      format: draftFormat,
      revision: base?.revision ?? 0,
      expectedRevision: base?.revision ?? 0,
    },
    resourceId,
  );
  let validDocument = true;
  if (draftFormat === "json") {
    try {
      JSON.parse(draft);
    } catch {
      validDocument = false;
    }
  }
  const other = records.filter(
    (record) => !["message", "chat", "comment"].includes(record.type),
  );

  function renderMessage(item: ProductReportedMessage, index: number) {
    const { record } = item;
    const author = productCollaborationAuthor(record, presence);
    const authorName =
      author.name ?? l("Author not reported", "Autor no reportado");
    const parentAuthor = item.parent
      ? productCollaborationAuthor(item.parent, presence)
      : undefined;
    return (
      <li
        key={`${record.id}:${index}`}
        className={`rounded-xl border border-border bg-surface-subtle/30 p-4 ${
          item.relation === "reply" ? "ml-4 border-l-primary/35 sm:ml-8" : ""
        }`}
      >
        <div className="mb-3 flex flex-wrap items-start justify-between gap-3">
          <div className="flex min-w-0 items-center gap-3">
            <Avatar name={authorName} src={author.avatarUrl} />
            <div className="min-w-0">
              <p className="wrap-break-word text-xs font-semibold">
                {authorName}
              </p>
              {record.name && record.name !== author.name && (
                <p className="mt-1 wrap-break-word text-[11px] text-muted-foreground">
                  {record.name}
                </p>
              )}
            </div>
          </div>
          <span className="text-[10px] text-muted-foreground">
            <ProductDate value={record.updatedAt} />
          </span>
        </div>
        {item.parent && item.relation === "reply" && (
          <p className="mb-2 wrap-break-word text-[11px] text-muted-foreground">
            {l("Reply to", "Respuesta a")}{" "}
            {parentAuthor?.name ?? item.parent.name} · {item.parent.id}
          </p>
        )}
        {item.relation === "parent-unavailable" && (
          <p className="mb-2 wrap-break-word text-[11px] text-muted-foreground">
            {l(
              "Parent message is not loaded",
              "El mensaje padre no está cargado",
            )}
            {" · "}
            {item.parentId}
          </p>
        )}
        {item.relation === "invalid" && (
          <p className="mb-2 text-[11px] text-muted-foreground">
            {l(
              "Reply context is unavailable for this message.",
              "El contexto de respuesta no está disponible para este mensaje.",
            )}
          </p>
        )}
        <p className="whitespace-pre-wrap wrap-break-word text-xs leading-7">
          {record.description}
        </p>
        <div className="mt-3 flex flex-wrap items-center justify-between gap-2">
          <ProductStatus value={record.status} />
          {item.replyTarget && productSupportsReplies(publishAction) && (
            <Button
              size="sm"
              variant="ghost"
              disabled={!canReply || write.pending || scopeStale}
              aria-label={`${l("Reply to", "Responder a")} ${authorName} · ${record.id}`}
              onClick={() => {
                setReply(item.replyTarget!);
                setSelectedThread(item.replyTarget!.threadId);
                setReview(null);
                messageInput.current?.focus();
              }}
            >
              <Reply className="size-3.5" />
              {l("Reply", "Responder")}
            </Button>
          )}
        </div>
      </li>
    );
  }

  return (
    <div className="space-y-5">
      <ProductPanel
        title={l("Shared workspace", "Espacio compartido")}
        description={l(
          "Follow messages and document revisions within the selected resource.",
          "Sigue mensajes y revisiones de documentos dentro del recurso seleccionado.",
        )}
      >
        <ProductResourcePicker
          {...resources}
          value={resourceId}
          onChange={(value) => {
            read.reset();
            write.reset();
            current.current.resourceId = value;
            setResourceId(value);
            setRecords([]);
            setPresence([]);
            setSelectedThread("");
            setReply(null);
            setMessage("");
            setExtra({});
            setBase(null);
            setDraft("");
            setDraftTitle("");
            setDraftFormat("markdown");
            setRemote(null);
            setCursor("");
            setLastUpdate(null);
            setWatermark("");
            setReview(null);
          }}
          disabled={write.pending}
        />
        <div className="mt-4">
          <ProductFields
            action={queryAction}
            values={extra}
            onChange={(value) => {
              setExtra(value);
              setReview(null);
            }}
            exclude={["resourceId", "view", "cursor", "since"]}
            disabled={write.pending || scopeStale}
          />
        </div>
        <div className="mt-4 flex flex-wrap items-center justify-between gap-3">
          <label className="flex min-h-11 items-center gap-3 text-xs">
            <Checkbox
              checked={follow}
              onCheckedChange={setFollow}
              disabled={scopeStale}
            />
            {props.subscribe || props.adapter.subscribe
              ? l("Follow live updates", "Seguir actualizaciones en vivo")
              : l("Refresh every 15 seconds", "Actualizar cada 15 segundos")}
          </label>
          <Button
            variant="outline"
            loading={read.pending}
            disabled={!queryAction || write.pending || scopeStale}
            onClick={() => {
              void load();
            }}
          >
            <RefreshCw />
            {l("Refresh room", "Actualizar espacio")}
          </Button>
        </div>
        <div
          role="status"
          className="mt-3 flex flex-wrap items-center gap-3 text-xs text-muted-foreground"
        >
          {lastUpdate ? (
            <>
              <span>
                {stale
                  ? l(
                      "Updates may be stale",
                      "Las actualizaciones pueden estar desfasadas",
                    )
                  : l("Recently updated", "Actualizado recientemente")}
              </span>
              <ProductDate value={lastUpdate} />
            </>
          ) : (
            <span>
              {l(
                "No updates received yet",
                "Aún no se han recibido actualizaciones",
              )}
            </span>
          )}
          {(props.subscribe || props.adapter.subscribe) && follow && (
            <>
              <ProductStatus value={streamState} />
              <Button
                size="sm"
                variant="ghost"
                onClick={() => setStreamEpoch((value) => value + 1)}
              >
                {l("Reconnect from cursor", "Reconectar desde cursor")}
              </Button>
            </>
          )}
        </div>
        {streamError && (
          <p role="alert" className="mt-3 text-xs text-destructive-foreground">
            {l(
              "The live connection was interrupted. Reconnect or refresh the room.",
              "La conexión en vivo se interrumpió. Reconecta o actualiza el espacio.",
            )}
          </p>
        )}
        {scopeStale && (
          <p role="alert" className="mt-3 text-xs text-destructive-foreground">
            {l(
              "The connection scope changed. Reopen its settings before sending another action.",
              "El alcance de la conexión cambió. Vuelve a abrir su configuración antes de enviar otra acción.",
            )}
          </p>
        )}
        <div className="mt-4">
          <ProductOperationFeedback operation={read} />
          <ProductActionUnavailable action={queryAction} />
        </div>
      </ProductPanel>
      <div className="grid items-start gap-5 xl:grid-cols-[2fr_1fr]">
        <ProductPanel title={l("Conversation", "Conversación")}>
          {conversation.threads.length > 0 && (
            <div className="mb-5">
              <Select
                label={l("Reported threads", "Hilos reportados")}
                value={selectedThread}
                onValueChange={(value) => {
                  setSelectedThread(value);
                  setReply(null);
                  setReview(null);
                }}
                options={[
                  {
                    value: "",
                    label: l(
                      "All room messages",
                      "Todos los mensajes del espacio",
                    ),
                  },
                  ...conversation.threads.map((thread) => ({
                    value: thread.id,
                    label: `${l("Thread", "Hilo")} · ${thread.id}`,
                  })),
                ]}
                disabled={write.pending || scopeStale}
              />
            </div>
          )}
          {conversation.messages.length ? (
            <div className="space-y-5">
              {!selectedThread && conversation.flat.length > 0 && (
                <section
                  aria-label={l("Room messages", "Mensajes del espacio")}
                >
                  {conversation.threads.length > 0 && (
                    <p className="mb-3 text-xs font-medium text-muted-foreground">
                      {l("Room messages", "Mensajes del espacio")}
                    </p>
                  )}
                  <ol className="space-y-3">
                    {conversation.flat.map(renderMessage)}
                  </ol>
                </section>
              )}
              {visibleThreads.map((thread) => (
                <section
                  key={thread.id}
                  aria-label={`${l("Thread", "Hilo")} ${thread.id}`}
                  className="space-y-3 rounded-xl border border-border bg-surface-subtle/15 p-3 sm:p-4"
                >
                  <h4 className="flex items-start gap-2 wrap-break-word text-xs font-medium">
                    <MessageSquare className="mt-0.5 size-3.5 shrink-0 text-primary" />
                    <span>
                      {l("Thread", "Hilo")} · {thread.id}
                    </span>
                  </h4>
                  <ol className="space-y-3">
                    {thread.messages.map(renderMessage)}
                  </ol>
                </section>
              ))}
              {selectedThread && !visibleThreads.length && (
                <ProductEmpty>
                  {l(
                    "This thread is no longer loaded. Show all room messages to choose another.",
                    "Este hilo ya no está cargado. Muestra todos los mensajes para elegir otro.",
                  )}
                  <Button
                    className="mt-3"
                    variant="outline"
                    disabled={write.pending || scopeStale}
                    onClick={() => {
                      setSelectedThread("");
                      setReply(null);
                      setReview(null);
                    }}
                  >
                    {l("Show all messages", "Mostrar todos los mensajes")}
                  </Button>
                </ProductEmpty>
              )}
              {!conversation.threads.length && (
                <p className="text-[11px] leading-5 text-muted-foreground">
                  {l(
                    "No thread information has been reported for these messages.",
                    "No se ha reportado información de hilos para estos mensajes.",
                  )}
                </p>
              )}
            </div>
          ) : (
            <ProductEmpty>
              {l(
                "Refresh this room to load its conversation.",
                "Actualiza este espacio para cargar la conversación.",
              )}
            </ProductEmpty>
          )}
          {records.length === 100 && (
            <p className="mt-3 text-xs text-muted-foreground">
              {l(
                "Showing the latest 100 loaded records.",
                "Se muestran los últimos 100 registros cargados.",
              )}
            </p>
          )}
          <div className="mt-5 space-y-4">
            {reply && (
              <div className="space-y-2 rounded-xl border border-primary/30 bg-primary/5 p-3">
                <p
                  role="status"
                  className="wrap-break-word text-xs font-medium"
                >
                  {l("Replying in thread", "Respondiendo en el hilo")}{" "}
                  {reply.threadId}
                </p>
                <p className="wrap-break-word text-[11px] text-muted-foreground">
                  {l("Parent message", "Mensaje padre")} · {reply.parentId}
                </p>
                {replyMessage && (
                  <p className="line-clamp-3 whitespace-pre-wrap wrap-break-word text-xs leading-6">
                    {replyMessage.record.description}
                  </p>
                )}
                {!replyCurrent && (
                  <p
                    role="alert"
                    className="text-xs text-destructive-foreground"
                  >
                    {l(
                      "This reply target is no longer available in the selected room. Choose a loaded message or start a new room message.",
                      "El destino de la respuesta ya no está disponible en este espacio. Elige un mensaje cargado o inicia un mensaje nuevo.",
                    )}
                  </p>
                )}
                <Button
                  size="sm"
                  variant="ghost"
                  disabled={write.pending || scopeStale}
                  onClick={() => {
                    setReply(null);
                    setReview(null);
                    messageInput.current?.focus();
                  }}
                >
                  {l("New room message", "Nuevo mensaje del espacio")}
                </Button>
              </div>
            )}
            <ProductLabeledTextarea
              ref={messageInput}
              label={reply ? l("Reply", "Respuesta") : l("Message", "Mensaje")}
              value={message}
              onChange={(event) => {
                setMessage(event.target.value);
                setReview(null);
              }}
              disabled={write.pending || scopeStale}
            />
            <ProductFields
              action={publishAction}
              values={extra}
              onChange={(value) => {
                setExtra(value);
                setReview(null);
              }}
              exclude={[
                "resourceId",
                "roomId",
                "message",
                "content",
                "channelId",
                "threadId",
                "parentId",
                "authorId",
                "authorName",
              ]}
              disabled={write.pending || scopeStale}
            />
            <Button
              appearance="gradient"
              disabled={
                !publishAction ||
                !canPublish ||
                !message.trim() ||
                !messageValues ||
                write.pending ||
                scopeStale ||
                Boolean(
                  messageValues &&
                  invalidProductField(publishAction, messageValues),
                )
              }
              onClick={() =>
                stage(publishAction, { message, content: message })
              }
            >
              <Send />
              {reply
                ? l("Review reply", "Revisar respuesta")
                : l("Review message", "Revisar mensaje")}
            </Button>
            {publishAction && !canPublish && (
              <p className="text-xs leading-6 text-muted-foreground">
                {l(
                  "Publishing needs additional connection permissions. Review the connection settings.",
                  "Publicar requiere permisos adicionales. Revisa la configuración de la conexión.",
                )}
              </p>
            )}
            <ProductActionUnavailable action={publishAction} />
            {messageValues && (
              <ProductValidation
                action={publishAction}
                values={messageValues}
              />
            )}
          </div>
          {other.length > 0 && (
            <details className="mt-5">
              <summary className="cursor-pointer text-xs font-medium">
                {l("Other room records", "Otros registros del espacio")}
              </summary>
              <ProductRecordList records={other} />
            </details>
          )}
        </ProductPanel>
        <ProductPanel
          title={
            <span className="flex items-center gap-2">
              <Users className="size-4" />
              {l("Presence", "Presencia")}
            </span>
          }
          description={l(
            "Only participants reported by this connection are shown.",
            "Solo se muestran participantes reportados por esta conexión.",
          )}
        >
          {presence.length ? (
            <ul className="space-y-3">
              {presence.map((record) => (
                <li
                  key={record.id}
                  className="flex flex-wrap items-center justify-between gap-2"
                >
                  <div className="flex min-w-0 items-center gap-3">
                    <Avatar
                      name={record.name}
                      src={productPresenceAvatarUrl(record.fields?.avatarUrl)}
                    />
                    <div className="min-w-0">
                      <p className="wrap-break-word text-xs font-medium">
                        {record.name}
                      </p>
                      {record.updatedAt && (
                        <p className="mt-1 text-[10px] text-muted-foreground">
                          <ProductDate value={record.updatedAt} />
                        </p>
                      )}
                    </div>
                  </div>
                  <ProductStatus value={record.status} />
                </li>
              ))}
            </ul>
          ) : (
            <ProductEmpty>
              {l(
                "No presence information has been received.",
                "No se ha recibido información de presencia.",
              )}
            </ProductEmpty>
          )}
        </ProductPanel>
      </div>
      {saveAction && (
        <ProductPanel
          title={l(
            "Resumable shared document",
            "Documento compartido reanudable",
          )}
        >
          <div className="mb-4 flex flex-wrap items-center gap-3">
            <Button
              variant="outline"
              loading={read.pending}
              onClick={() => {
                void load("document");
              }}
            >
              {l("Pull document revision", "Cargar revisión del documento")}
            </Button>
            {base && (
              <span className="text-xs text-muted-foreground">
                {base.title} · {l("Revision", "Revisión")} {base.revision}
              </span>
            )}
          </div>
          {base ? (
            <div className="grid gap-5 xl:grid-cols-2">
              <div className="space-y-4">
                {props.renderEditor ? (
                  props.renderEditor({
                    value: {
                      ...base,
                      title: draftTitle,
                      content: draft,
                      format: draftFormat,
                    },
                    onChange: (value) => {
                      setDraft(value.content);
                      setDraftTitle(value.title);
                      setDraftFormat(value.format);
                      setReview(null);
                    },
                    disabled: write.pending,
                    locale,
                  })
                ) : (
                  <>
                    <label className="block space-y-2 text-xs font-medium">
                      {l("Title", "Título")}
                      <Input
                        value={draftTitle}
                        onChange={(event) => {
                          setDraftTitle(event.target.value);
                          setReview(null);
                        }}
                        disabled={write.pending || scopeStale}
                      />
                    </label>
                    <Select
                      label={l("Document format", "Formato del documento")}
                      value={draftFormat}
                      onValueChange={(value) => {
                        setDraftFormat(value as IntegrationDocument["format"]);
                        setReview(null);
                      }}
                      options={(
                        saveAction.fields.find((field) => field.id === "format")
                          ?.options ?? [
                          {
                            value: "markdown",
                            label: { en: "Markdown", es: "Markdown" },
                          },
                          {
                            value: "text",
                            label: { en: "Plain text", es: "Texto" },
                          },
                          { value: "json", label: { en: "JSON", es: "JSON" } },
                        ]
                      ).map((option) => ({
                        value: option.value,
                        label: l(option.label.en, option.label.es),
                      }))}
                      disabled={write.pending || scopeStale}
                    />
                    <ProductLabeledTextarea
                      label={l("Shared document", "Documento compartido")}
                      value={draft}
                      onChange={(event) => {
                        setDraft(event.target.value);
                        setReview(null);
                      }}
                      disabled={write.pending || scopeStale}
                      aria-invalid={!validDocument}
                    />
                  </>
                )}
                <ProductFields
                  action={saveAction}
                  values={extra}
                  onChange={(value) => {
                    setExtra(value);
                    setReview(null);
                  }}
                  exclude={[
                    "resourceId",
                    "documentId",
                    "id",
                    "title",
                    "content",
                    "format",
                    "revision",
                    "expectedRevision",
                  ]}
                  disabled={write.pending}
                />
                <Button
                  appearance="gradient"
                  disabled={
                    write.pending ||
                    Boolean(remote) ||
                    write.errorCode === "conflict" ||
                    scopeStale ||
                    !validDocument ||
                    Boolean(invalidProductField(saveAction, documentValues))
                  }
                  onClick={() =>
                    stage(saveAction, {
                      ...documentValues,
                    })
                  }
                >
                  <Save />
                  {l("Review document update", "Revisar actualización")}
                </Button>
              </div>
              <ProductDocumentPreview content={draft} format={draftFormat} />
            </div>
          ) : (
            <ProductEmpty>
              {l(
                "Load a document revision before editing.",
                "Carga una revisión del documento antes de editar.",
              )}
            </ProductEmpty>
          )}
          {remote && (
            <div
              role="alert"
              className="mt-4 space-y-3 rounded-xl border border-primary/30 p-4"
            >
              <p className="text-xs">
                {l(
                  "A newer document arrived. Your changes are preserved.",
                  "Llegó un documento más reciente. Tus cambios se conservan.",
                )}
              </p>
              <ProductDocumentPreview
                content={remote.content}
                format={remote.format}
              />
              <div className="flex flex-wrap gap-2">
                <Button
                  variant="outline"
                  onClick={() => {
                    setBase(remote);
                    setDraft(remote.content);
                    setDraftTitle(remote.title);
                    setDraftFormat(remote.format);
                    setRemote(null);
                    write.reset();
                    setReview(null);
                  }}
                >
                  {l("Use remote document", "Usar documento remoto")}
                </Button>
                <Button
                  onClick={() => {
                    setBase(remote);
                    setRemote(null);
                    write.reset();
                    setReview(null);
                  }}
                >
                  {l(
                    "Keep edits with latest revision",
                    "Conservar cambios con revisión actual",
                  )}
                </Button>
              </div>
            </div>
          )}
          {checkpointAction && (
            <div className="mt-5 space-y-3">
              <ProductFields
                action={checkpointAction}
                values={extra}
                onChange={(value) => {
                  setExtra(value);
                  setReview(null);
                }}
                exclude={["resourceId", "documentId", "revision", "cursor"]}
                disabled={write.pending}
              />
              <Button
                variant="outline"
                disabled={!base || write.pending}
                onClick={() =>
                  stage(checkpointAction, {
                    documentId: base?.id ?? "",
                    revision: base?.revision ?? 0,
                    cursor,
                  })
                }
              >
                {l("Review checkpoint", "Revisar punto de control")}
              </Button>
            </div>
          )}
        </ProductPanel>
      )}
      <ProductOperationFeedback operation={write} />
      {write.result && (
        <ProductPanel title={l("Action outcome", "Resultado de la acción")}>
          <ProductResult result={write.result} />
        </ProductPanel>
      )}
      {review && (
        <ProductReview
          action={review.action}
          values={review.values}
          pending={write.pending}
          disabled={scopeStale || !reviewCurrent}
          grantedPermissions={props.connection.grantedPermissions}
          onConfirm={() => {
            void submit();
          }}
          onReject={() => setReview(null)}
        >
          {!reviewCurrent && (
            <p
              role="alert"
              className="mb-3 text-xs text-destructive-foreground"
            >
              {l(
                "The room or reply target changed. Return to editing and review an available target before sending.",
                "El espacio o destino de la respuesta cambió. Vuelve a editar y revisa un destino disponible antes de enviar.",
              )}
            </p>
          )}
        </ProductReview>
      )}
    </div>
  );
}

import type {
  IntegrationConnection,
  IntegrationRecord,
  IntegrationResult,
  IntegrationUpdate,
} from "../../lib/integrations/contracts";
import type { DataTableQuery } from "../../lib/data-query";

export type ProductDataUpdate =
  | { kind: "ignore" }
  | { kind: "scope-changed" }
  | { kind: "rows"; records: IntegrationRecord[] };

/**
 * Connection-wide result DTOs carry no query/page identity. They identify when
 * remote membership, sorting and totals need revalidation with the current query.
 */
export function productDataUpdate(
  update: IntegrationUpdate,
  connection: IntegrationConnection,
  resourceId: string,
): ProductDataUpdate {
  if (
    connection.status !== "connected" ||
    !connection.resourceIds.includes(resourceId)
  )
    return { kind: "ignore" };
  if (update.kind === "connection") {
    const next = update.connection;
    if (
      next.id !== connection.id ||
      next.integrationId !== connection.integrationId ||
      next.workspaceId !== connection.workspaceId
    )
      return { kind: "ignore" };
    const scope = (item: IntegrationConnection) =>
      JSON.stringify([
        item.status,
        item.providerOptionId,
        item.revision,
        [...item.resourceIds].sort(),
        [...item.grantedPermissions].sort(),
      ]);
    return scope(next) === scope(connection)
      ? { kind: "ignore" }
      : { kind: "scope-changed" };
  }
  if (update.kind !== "result") return { kind: "ignore" };
  const result = update.result;
  const records =
    result.kind === "record"
      ? [result.record]
      : result.kind === "records"
        ? result.records
        : undefined;
  if (!records) return { kind: "ignore" };
  const matching: IntegrationRecord[] = [];
  let unspecifiedResource = records.length === 0;
  let otherAuthorizedResource = false;
  for (const record of records) {
    const fields = record.fields ?? {};
    if (
      (fields.workspaceId !== undefined &&
        fields.workspaceId !== connection.workspaceId) ||
      (fields.connectionId !== undefined &&
        fields.connectionId !== connection.id) ||
      (fields.integrationId !== undefined &&
        fields.integrationId !== connection.integrationId)
    )
      continue;
    if (fields.resourceId === undefined) {
      unspecifiedResource = true;
      continue;
    }
    if (fields.resourceId === resourceId) matching.push(record);
    else if (
      typeof fields.resourceId === "string" &&
      connection.resourceIds.includes(fields.resourceId)
    )
      otherAuthorizedResource = true;
  }
  // An authenticated query can join several granted resources. A broad event
  // may invalidate that membership, but never identifies the current page.
  return matching.length || unspecifiedResource || otherAuthorizedResource
    ? { kind: "rows", records: matching }
    : { kind: "ignore" };
}

/** Prevent a slower query from replacing rows invalidated by a live update. */
export function createProductDataEpoch() {
  let value = 0;
  return {
    invalidate() {
      value += 1;
    },
    capture() {
      return value;
    },
    isCurrent(snapshot: number) {
      return snapshot === value;
    },
  };
}

/** Only a subscription bound to this exact server query may replace its page. */
export function productReportedDataPage(
  result: IntegrationResult,
  connection: IntegrationConnection,
  resourceId: string,
  query: DataTableQuery,
) {
  if (
    result.kind !== "records" ||
    connection.status !== "connected" ||
    !connection.resourceIds.includes(resourceId) ||
    result.records.length > query.pagination.pageSize ||
    result.total < result.records.length ||
    new Set(result.records.map((record) => record.id)).size !==
      result.records.length
  )
    return undefined;
  if (
    result.records.some((record) => {
      const fields = record.fields ?? {};
      return (
        (fields.workspaceId !== undefined &&
          fields.workspaceId !== connection.workspaceId) ||
        (fields.connectionId !== undefined &&
          fields.connectionId !== connection.id) ||
        (fields.integrationId !== undefined &&
          fields.integrationId !== connection.integrationId) ||
        (fields.resourceId !== undefined &&
          (typeof fields.resourceId !== "string" ||
            !connection.resourceIds.includes(fields.resourceId)))
      );
    })
  )
    return undefined;
  return result;
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { ColumnDef, RowSelectionState } from "@tanstack/react-table";
import { Pencil, RefreshCw, Save } from "lucide-react";
import { useLanguage } from "@/hooks/use-language";
import { useIntegrationOperation } from "@/hooks/use-integration-operation";
import { DataTable, type DataTableQuery } from "@/components/ui/data-table";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select } from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { parseIntegrationUpdate } from "@/lib/integrations/validation";
import type {
  IntegrationRecord,
  IntegrationUpdate,
  IntegrationValues,
  IntegrationWorkbenchProps,
} from "@/lib/integrations/contracts";
import {
  findProductAction,
  invalidProductField,
  optimisticProductRecord,
  parseProductFields,
  productActionValues,
  productQueryValues,
  rollbackProductRecord,
} from "./product-model";
import {
  ProductActionUnavailable,
  ProductDate,
  ProductDocumentPreview,
  ProductFields,
  ProductLabeledTextarea,
  ProductOperationFeedback,
  ProductPanel,
  ProductResourcePicker,
  ProductResult,
  ProductReview,
  ProductStatus,
  ProductValidation,
  useProductResources,
} from "./product-ui";
import {
  createProductDataEpoch,
  productDataUpdate,
  productReportedDataPage,
} from "./product-data-reactivity";
import { startProductSubscription } from "./product-subscription";

const initialQuery: DataTableQuery = {
  search: "",
  filters: [],
  sorting: [],
  pagination: { pageIndex: 0, pageSize: 10 },
};

export type ProductDataSubscription = {
  integrationId: string;
  connectionId: string;
  workspaceId: string;
  resourceId: string;
  actionId: string;
  query: DataTableQuery;
  values: IntegrationValues;
  querySignature: string;
  signal: AbortSignal;
  /** Complete, server-filtered and server-paginated page for this subscription. */
  onUpdate: (update: IntegrationUpdate) => void;
  onError: () => void;
};

export type ProductDataSubscribe = (
  subscription: ProductDataSubscription,
) => (() => void) | Promise<() => void>;

export function ProductDataWorkbench(
  props: IntegrationWorkbenchProps & { subscribeData?: ProductDataSubscribe },
) {
  const { l } = useLanguage();
  const { adapter, connection, definition, subscribeData } = props;
  const { workspaceId, signal: scopeSignal } = props.scope;
  const read = useIntegrationOperation(props);
  const write = useIntegrationOperation(props);
  const readRun = read.run;
  const readCancel = read.cancel;
  const writeCancel = write.cancel;
  const writeReset = write.reset;
  const resources = useProductResources(props);
  const queryAction = findProductAction(props.definition, "query");
  const saveAction = findProductAction(
    props.definition,
    "save-record",
    "update-record",
  );
  const canSave = Boolean(saveAction);
  const [resourceId, setResourceId] = useState(
    props.connection.resourceIds[0] ?? "",
  );
  const [query, setQuery] = useState<DataTableQuery>(initialQuery);
  const [readValues, setReadValues] = useState<IntegrationValues>({});
  const [records, setRecords] = useState<IntegrationRecord[]>([]);
  const [total, setTotal] = useState(0);
  const [selection, setSelection] = useState<RowSelectionState>({});
  const [base, setBase] = useState<IntegrationRecord | null>(null);
  const [draft, setDraft] = useState<IntegrationValues>({});
  const [fieldsText, setFieldsText] = useState("{}");
  const [review, setReview] = useState<IntegrationValues | null>(null);
  const [loaded, setLoaded] = useState(false);
  const [refresh, setRefresh] = useState(0);
  const [reactive, setReactive] = useState(
    Boolean(props.subscribeData || props.adapter.subscribe),
  );
  const [reactiveRetry, setReactiveRetry] = useState(0);
  const [reactiveError, setReactiveError] = useState(false);
  const [reactiveAt, setReactiveAt] = useState<string | null>(null);
  const [scopeStale, setScopeStale] = useState(false);
  const [dataEpoch] = useState(createProductDataEpoch);
  const queryIdentity = JSON.stringify([query, readValues]);
  const subscriptionDispose = useRef<(() => void) | null>(null);
  const stopReactive = useCallback(() => {
    subscriptionDispose.current?.();
    subscriptionDispose.current = null;
  }, []);
  const allowed = props.connection.resourceIds.includes(resourceId);
  const cursorPages = useRef<{ key: string; pages: Record<number, string> }>({
    key: "",
    pages: {},
  });
  const mutationSequence = useRef(0);
  const statusField = saveAction?.fields.find((field) => field.id === "status");

  const load = useCallback(async () => {
    if (!queryAction || !allowed || scopeStale) return;
    const epoch = dataEpoch.capture();
    const cursorKey = JSON.stringify([
      resourceId,
      readValues,
      query.search,
      query.filters,
      query.sorting,
      query.pagination.pageSize,
    ]);
    if (cursorPages.current.key !== cursorKey)
      cursorPages.current = { key: cursorKey, pages: {} };
    const values = productActionValues(
      queryAction,
      {
        ...readValues,
        ...productQueryValues(query, resourceId),
        cursor:
          cursorPages.current.pages[query.pagination.pageIndex] ??
          readValues.cursor ??
          "",
      },
      resourceId,
    );
    if (invalidProductField(queryAction, values)) return;
    const result = await readRun(queryAction, values);
    if (!dataEpoch.isCurrent(epoch)) return;
    if (result?.kind === "records") {
      if (result.cursor)
        cursorPages.current.pages[query.pagination.pageIndex + 1] =
          result.cursor;
      setRecords(result.records);
      setTotal(result.total);
      setLoaded(true);
    } else if (result?.kind === "record") {
      setRecords([result.record]);
      setTotal(1);
      setLoaded(true);
    }
  }, [
    queryAction,
    allowed,
    scopeStale,
    dataEpoch,
    readValues,
    query,
    resourceId,
    readRun,
  ]);

  useEffect(() => {
    const timer = setTimeout(() => {
      void load();
    }, 250);
    return () => {
      clearTimeout(timer);
      readCancel();
    };
  }, [load, refresh, readCancel]);

  useEffect(() => {
    if (
      (!subscribeData && !adapter.subscribe) ||
      !reactive ||
      !allowed ||
      scopeStale ||
      !queryAction ||
      queryAction.requiredPermissions?.some(
        (permission) => !connection.grantedPermissions.includes(permission),
      )
    )
      return;
    const streamValues = productActionValues(
      queryAction,
      {
        ...readValues,
        ...productQueryValues(query, resourceId),
        cursor:
          cursorPages.current.pages[query.pagination.pageIndex] ??
          readValues.cursor ??
          "",
      },
      resourceId,
    );
    if (invalidProductField(queryAction, streamValues)) return;
    const seen = new Set<string>();
    setReactiveError(false);
    setReactiveAt(null);
    const dispose = startProductSubscription(
      (listener, signal) =>
        subscribeData
          ? subscribeData({
              integrationId: definition.id,
              connectionId: connection.id,
              workspaceId,
              resourceId,
              actionId: queryAction.id,
              query: structuredClone(query),
              values: structuredClone(streamValues),
              querySignature: JSON.stringify([
                definition.id,
                connection.id,
                connection.revision,
                connection.providerOptionId,
                workspaceId,
                [...connection.resourceIds].sort(),
                [...connection.grantedPermissions].sort(),
                resourceId,
                queryAction.id,
                queryIdentity,
                streamValues,
              ]),
              signal,
              onUpdate: listener,
              onError: () => {
                if (!signal.aborted) setReactiveError(true);
              },
            })
          : adapter.subscribe!(connection.id, listener, {
              workspaceId,
              signal,
            }),
      {
        signal: scopeSignal,
        onUpdate: (raw) => {
          let update;
          try {
            update = parseIntegrationUpdate(raw, definition, connection.id, {
              workspaceId,
              signal: scopeSignal,
            });
          } catch {
            setReactiveError(true);
            return;
          }
          const change = productDataUpdate(update, connection, resourceId);
          if (change.kind === "ignore") return;
          if (change.kind === "scope-changed") {
            dataEpoch.invalidate();
            readCancel();
            writeCancel();
            setScopeStale(true);
            setRecords([]);
            setTotal(0);
            setBase(null);
            setReview(null);
            setSelection({});
            return;
          }
          const signature = JSON.stringify(update);
          if (seen.has(signature)) return;
          const page =
            subscribeData &&
            update.kind === "result" &&
            update.result.kind === "records"
              ? productReportedDataPage(
                  update.result,
                  connection,
                  resourceId,
                  query,
                )
              : undefined;
          if (
            subscribeData &&
            update.kind === "result" &&
            update.result.kind === "records" &&
            !page
          ) {
            setReactiveError(true);
            return;
          }
          seen.add(signature);
          if (seen.size > 128) seen.delete(seen.values().next().value!);
          dataEpoch.invalidate();
          readCancel();
          if (page) {
            setRecords(page.records);
            setTotal(page.total);
            setLoaded(true);
            if (page.cursor)
              cursorPages.current.pages[query.pagination.pageIndex + 1] =
                page.cursor;
          } else {
            // Connection-wide events carry no query identity. They invalidate
            // this query and never patch a different filter, sort or page.
            setRefresh((value) => value + 1);
          }
          setReactiveAt(new Date().toISOString());
          setReactiveError(false);
        },
        onError: () => setReactiveError(true),
      },
    );
    subscriptionDispose.current = dispose;
    return () => {
      dispose();
      if (subscriptionDispose.current === dispose)
        subscriptionDispose.current = null;
    };
  }, [
    adapter,
    subscribeData,
    connection,
    definition,
    workspaceId,
    scopeSignal,
    resourceId,
    queryIdentity,
    query,
    readValues,
    queryAction,
    reactive,
    reactiveRetry,
    allowed,
    scopeStale,
    dataEpoch,
    readCancel,
    writeCancel,
  ]);

  const edit = useCallback(
    (record: IntegrationRecord) => {
      setBase(record);
      setDraft({
        name: record.name,
        status: record.status,
        description: record.description,
      });
      setFieldsText(JSON.stringify(record.fields ?? {}, null, 2));
      setSelection({ [record.id]: true });
      setReview(null);
      writeReset();
    },
    [writeReset, setBase, setDraft, setFieldsText, setSelection, setReview],
  );

  const columns = useMemo<ColumnDef<IntegrationRecord>[]>(
    () => [
      {
        accessorKey: "name",
        header: l("Record", "Registro"),
        cell: ({ row }) => (
          <div>
            <p className="font-medium">{row.original.name}</p>
            <p className="mt-1 text-[10px] text-muted-foreground">
              {row.original.id}
            </p>
          </div>
        ),
      },
      {
        accessorKey: "status",
        header: l("Status", "Estado"),
        cell: ({ row }) => (
          <ProductStatus
            value={
              row.original.updatedAt.startsWith("pending:")
                ? "pending"
                : row.original.status
            }
          />
        ),
      },
      { accessorKey: "type", header: l("Type", "Tipo") },
      {
        accessorKey: "updatedAt",
        header: l("Updated", "Actualizado"),
        cell: ({ row }) => <ProductDate value={row.original.updatedAt} />,
      },
      {
        id: "edit",
        header: l("Actions", "Acciones"),
        enableSorting: false,
        cell: ({ row }) => (
          <Button
            size="sm"
            variant="ghost"
            disabled={write.pending || !canSave}
            onClick={() => edit(row.original)}
            aria-label={`${l("Edit", "Editar")} ${row.original.name}`}
          >
            <Pencil />
            {l("Edit", "Editar")}
          </Button>
        ),
      },
    ],
    [l, canSave, write.pending, edit],
  );

  const parsed = parseProductFields(fieldsText);
  const prepared = productActionValues(
    saveAction,
    {
      ...draft,
      ...(base
        ? {
            id: base.id,
            recordId: base.id,
            expectedUpdatedAt: base.updatedAt,
            ...(base.fields?.revision !== undefined
              ? { revision: base.fields.revision }
              : {}),
          }
        : {}),
      fields: fieldsText,
    },
    resourceId,
  );
  const invalid = invalidProductField(saveAction, prepared);
  const latest = base
    ? records.find((record) => record.id === base.id)
    : undefined;
  const conflict = write.errorCode === "conflict";

  async function save() {
    if (
      !saveAction ||
      !base ||
      !review ||
      !parsed.ok ||
      write.pending ||
      scopeStale
    )
      return;
    const original = base;
    const marker = `pending:${props.connection.id}:${props.connection.revision}:${original.id}:${++mutationSequence.current}`;
    const optimistic = optimisticProductRecord(original, review, marker);
    setRecords((items) =>
      items.map((item) => (item.id === original.id ? optimistic : item)),
    );
    const result = await write.run(saveAction, review);
    if (result?.kind === "record" && result.record.id === original.id) {
      setRecords((items) =>
        items.map((item) => (item.id === original.id ? result.record : item)),
      );
      setBase(result.record);
      setDraft({
        name: result.record.name,
        status: result.record.status,
        description: result.record.description,
      });
      setFieldsText(JSON.stringify(result.record.fields ?? {}, null, 2));
      setReview(null);
      setRefresh((value) => value + 1);
    } else {
      setRecords((items) => rollbackProductRecord(items, original, marker));
      if (result) setReview(null);
    }
  }

  return (
    <div className="space-y-5">
      <ProductPanel
        title={l("Explore your data", "Explora tus datos")}
        description={l(
          "Search, filters, sorting and pages are applied by your connected data source.",
          "La fuente conectada aplica la búsqueda, los filtros, el orden y las páginas.",
        )}
      >
        {(props.subscribeData || props.adapter.subscribe) && (
          <div className="mb-4 space-y-3 rounded-xl border border-border bg-surface-subtle/40 p-3">
            <label className="flex min-h-11 items-center gap-3 text-xs">
              <Checkbox
                checked={reactive}
                onCheckedChange={(value) => {
                  if (!value) stopReactive();
                  setReactive(value);
                }}
                disabled={scopeStale}
              />
              {l("Follow reactive data", "Seguir datos reactivos")}
            </label>
            <p
              role="status"
              className="text-xs leading-6 text-muted-foreground"
            >
              {!reactive ? (
                l(
                  "Live updates paused. You can still refresh records.",
                  "Actualizaciones en vivo pausadas. Puedes actualizar los registros.",
                )
              ) : reactiveAt ? (
                <>
                  {l(
                    "Reactive update received",
                    "Actualización reactiva recibida",
                  )}{" "}
                  · <ProductDate value={reactiveAt} />
                </>
              ) : (
                l(
                  "Waiting for reactive rows from this connection.",
                  "Esperando filas reactivas de esta conexión.",
                )
              )}
            </p>
            {reactiveError && (
              <div
                role="alert"
                className="flex flex-wrap items-center gap-3 text-xs"
              >
                <p>
                  {l(
                    "The live update was unavailable or invalid. Refresh records or reconnect the live transport.",
                    "La actualización en vivo no estaba disponible o no era válida. Actualiza los registros o reconecta el transporte.",
                  )}
                </p>
                <Button
                  size="sm"
                  variant="outline"
                  disabled={scopeStale}
                  onClick={() => setReactiveRetry((value) => value + 1)}
                >
                  {l("Reconnect live data", "Reconectar datos en vivo")}
                </Button>
              </div>
            )}
          </div>
        )}
        {scopeStale && (
          <p
            role="alert"
            className="mb-4 rounded-xl border border-destructive/25 p-3 text-xs leading-6"
          >
            {l(
              "The connection scope changed. Reopen the connection before reading or changing records.",
              "El alcance de la conexión cambió. Vuelve a abrir la conexión antes de consultar o modificar registros.",
            )}
          </p>
        )}
        <div className="mb-4 grid gap-4 sm:grid-cols-2">
          <ProductResourcePicker
            {...resources}
            value={resourceId}
            onChange={(value) => {
              read.reset();
              write.reset();
              stopReactive();
              dataEpoch.invalidate();
              setReactiveAt(null);
              setResourceId(value);
              setRecords([]);
              setLoaded(false);
              setBase(null);
              setReview(null);
              setSelection({});
              setQuery(initialQuery);
            }}
            disabled={write.pending || scopeStale}
          />
          <label className="space-y-2 text-xs font-medium">
            {l("Status filter", "Filtro de estado")}
            <Input
              value={String(
                query.filters.find((filter) => filter.id === "status")?.value ??
                  "",
              )}
              placeholder={l("Any status", "Cualquier estado")}
              disabled={write.pending || scopeStale}
              onChange={(event) => {
                stopReactive();
                dataEpoch.invalidate();
                setQuery((current) => ({
                  ...current,
                  filters: event.target.value
                    ? [{ id: "status", value: event.target.value }]
                    : [],
                  pagination: { ...current.pagination, pageIndex: 0 },
                }));
              }}
            />
          </label>
        </div>
        <ProductFields
          action={queryAction}
          values={readValues}
          onChange={(values) => {
            stopReactive();
            dataEpoch.invalidate();
            setReadValues(values);
          }}
          disabled={write.pending || scopeStale}
          exclude={[
            "query",
            "search",
            "filter",
            "status",
            "page",
            "pageIndex",
            "pageSize",
            "limit",
            "offset",
            "sort",
            "order",
            "filters",
            "sorting",
            "queryState",
            "resourceId",
          ]}
        />
        <div className="my-4 flex justify-end">
          <Button
            variant="outline"
            loading={read.pending}
            disabled={!queryAction || !allowed || write.pending || scopeStale}
            onClick={() => setRefresh((value) => value + 1)}
          >
            <RefreshCw />
            {l("Refresh records", "Actualizar registros")}
          </Button>
        </div>
        <ProductActionUnavailable action={queryAction} />
        <DataTable
          mode="external"
          data={records}
          rowCount={total}
          columns={columns}
          query={query}
          onQueryChange={(value) => {
            if (!write.pending && !scopeStale) {
              stopReactive();
              dataEpoch.invalidate();
              setQuery(value);
            }
          }}
          rowSelection={selection}
          onRowSelectionChange={setSelection}
          pageSizeOptions={[5, 10, 25, 50]}
          columnVisibility
          loading={read.pending}
          error={read.error ?? undefined}
          onRetry={() => setRefresh((value) => value + 1)}
          labels={{
            search: l("Search records…", "Buscar registros…"),
            empty: l(
              loaded ? "No matching records" : "No records loaded",
              loaded
                ? "No hay registros coincidentes"
                : "No hay registros cargados",
            ),
            emptyDescription: l(
              "Choose an authorized source and adjust your query.",
              "Elige una fuente autorizada y ajusta la consulta.",
            ),
            previous: l("Previous page", "Página anterior"),
            next: l("Next page", "Página siguiente"),
            selectAll: l("Select this page", "Seleccionar esta página"),
            selectRow: l("Select record", "Seleccionar registro"),
            selected: l("selected", "seleccionados"),
            page: l("Page", "Página"),
            of: l("of", "de"),
            rows: l("records", "registros"),
            clear: l("Clear search", "Limpiar búsqueda"),
            error: l(
              "Could not load records",
              "No se pudieron cargar los registros",
            ),
            retry: l("Retry", "Reintentar"),
            loading: l("Loading records", "Cargando registros"),
            columns: l("Columns", "Columnas"),
            clearSelection: l("Clear selection", "Limpiar selección"),
            rowsPerPage: l("Records per page", "Registros por página"),
          }}
        />
        <div className="mt-3">
          <ProductOperationFeedback operation={read} />
        </div>
        {read.result && !["records", "record"].includes(read.result.kind) && (
          <ProductResult result={read.result} />
        )}
      </ProductPanel>
      {base && (
        <ProductPanel
          title={l("Edit record", "Editar registro")}
          description={
            <>
              {base.id} · {l("Base version", "Versión base")}:{" "}
              <ProductDate value={base.updatedAt} />
            </>
          }
        >
          <div className="grid gap-4 sm:grid-cols-2">
            <label className="space-y-2 text-xs font-medium">
              {l("Name", "Nombre")}
              <Input
                value={String(draft.name ?? "")}
                onChange={(event) => {
                  setReview(null);
                  setDraft({ ...draft, name: event.target.value });
                }}
                disabled={write.pending}
              />
            </label>
            <label className="space-y-2 text-xs font-medium">
              {l("Status", "Estado")}
              {statusField?.options?.length ? (
                <Select
                  aria-label={l("Status", "Estado")}
                  value={String(draft.status ?? "")}
                  options={statusField.options.map((option) => ({
                    value: option.value,
                    label: l(option.label.en, option.label.es),
                  }))}
                  onValueChange={(value) => {
                    setReview(null);
                    setDraft({ ...draft, status: value });
                  }}
                  disabled={write.pending}
                />
              ) : (
                <Input
                  value={String(draft.status ?? "")}
                  onChange={(event) => {
                    setReview(null);
                    setDraft({ ...draft, status: event.target.value });
                  }}
                  disabled={write.pending}
                />
              )}
            </label>
          </div>
          <div className="my-4">
            <ProductLabeledTextarea
              label={l("Description", "Descripción")}
              value={String(draft.description ?? "")}
              onChange={(event) => {
                setReview(null);
                setDraft({ ...draft, description: event.target.value });
              }}
              disabled={write.pending}
            />
          </div>
          <ProductFields
            action={saveAction}
            values={draft}
            onChange={(values) => {
              setReview(null);
              setDraft(values);
            }}
            disabled={write.pending}
            exclude={[
              "id",
              "recordId",
              "name",
              "status",
              "description",
              "fields",
              "resourceId",
              "revision",
              "expectedUpdatedAt",
            ]}
          />
          <div className="my-4">
            <ProductLabeledTextarea
              label={l(
                "Record fields · JSON object",
                "Campos del registro · Objeto JSON",
              )}
              value={fieldsText}
              spellCheck={false}
              className="font-mono text-xs"
              onChange={(event) => {
                setFieldsText(event.target.value);
                setReview(null);
              }}
              disabled={write.pending}
              aria-invalid={!parsed.ok}
            />
          </div>
          {!parsed.ok && (
            <p
              role="alert"
              className="mb-3 text-xs text-destructive-foreground"
            >
              {l(
                "Use valid JSON with text, numbers, booleans or lists of text.",
                "Usa JSON válido con texto, números, booleanos o listas de texto.",
              )}
            </p>
          )}
          <ProductValidation action={saveAction} values={prepared} />
          {conflict && (
            <div
              role="alert"
              className="mb-4 space-y-3 rounded-xl border border-primary/30 bg-accent/30 p-4"
            >
              <p className="text-xs leading-6">
                {l(
                  "Your draft is preserved. Refresh the records, compare the latest values, then choose a new base before retrying.",
                  "Tu borrador se conserva. Actualiza los registros, compara los valores actuales y elige una nueva base antes de reintentar.",
                )}
              </p>
              {latest && latest.updatedAt !== base.updatedAt && (
                <div className="grid gap-3 sm:grid-cols-2">
                  <div>
                    <p className="mb-1 text-xs font-semibold">
                      {l(
                        "Latest source values",
                        "Valores actuales de la fuente",
                      )}
                    </p>
                    <p className="text-xs leading-6">
                      {latest.name} · {latest.status}
                    </p>
                    <p className="text-xs leading-6">{latest.description}</p>
                  </div>
                  <div>
                    <p className="mb-1 text-xs font-semibold">
                      {l("Your draft", "Tu borrador")}
                    </p>
                    <p className="text-xs leading-6">
                      {String(draft.name)} · {String(draft.status)}
                    </p>
                    <p className="text-xs leading-6">
                      {String(draft.description)}
                    </p>
                  </div>
                </div>
              )}
              <div className="flex flex-wrap gap-2">
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => setRefresh((value) => value + 1)}
                  disabled={read.pending}
                >
                  {l("Reload source", "Recargar fuente")}
                </Button>
                <Button
                  size="sm"
                  disabled={!latest || latest.updatedAt === base.updatedAt}
                  onClick={() => {
                    if (latest) {
                      setBase(latest);
                      setReview(null);
                      write.reset();
                    }
                  }}
                >
                  {l(
                    "Keep edits, use latest base",
                    "Conservar cambios y usar base actual",
                  )}
                </Button>
              </div>
            </div>
          )}
          <div className="flex flex-wrap gap-2">
            <Button
              appearance="gradient"
              disabled={
                !saveAction ||
                !parsed.ok ||
                Boolean(invalid) ||
                write.pending ||
                conflict ||
                !String(draft.name ?? "").trim()
              }
              onClick={() => setReview(prepared)}
            >
              <Save />
              {l("Review changes", "Revisar cambios")}
            </Button>
            <Button
              variant="outline"
              disabled={write.pending}
              onClick={() => {
                setBase(null);
                setReview(null);
              }}
            >
              {l("Close editor", "Cerrar editor")}
            </Button>
          </div>
          <div className="mt-4">
            <ProductOperationFeedback operation={write} />
            <ProductActionUnavailable action={saveAction} />
          </div>
          {write.result && write.result.kind !== "record" && (
            <div className="mt-4">
              <ProductResult result={write.result} />
              <p className="mt-2 text-xs text-muted-foreground">
                {l(
                  "Refresh the source to confirm the stored version.",
                  "Actualiza la fuente para confirmar la versión guardada.",
                )}
              </p>
            </div>
          )}
        </ProductPanel>
      )}
      {review && saveAction && (
        <ProductReview
          action={saveAction}
          values={review}
          pending={write.pending}
          disabled={scopeStale}
          grantedPermissions={props.connection.grantedPermissions}
          onConfirm={() => {
            void save();
          }}
          onReject={() => setReview(null)}
        >
          <div className="mb-4">
            <p className="mb-2 text-xs font-semibold">
              {l("Record fields", "Campos del registro")}
            </p>
            <ProductDocumentPreview
              content={String(review.fields ?? "{}")}
              format="json"
            />
          </div>
        </ProductReview>
      )}
    </div>
  );
}

import type {
  IntegrationAction,
  IntegrationDocument,
} from "../../lib/integrations/contracts";

export function productDocumentFormats(action?: IntegrationAction) {
  const supported: IntegrationDocument["format"][] = [
    "markdown",
    "text",
    "json",
  ];
  const field = action?.fields.find((item) => item.id === "format");
  if (!field?.options?.length) return supported;
  return supported.filter((format) =>
    field.options!.some((option) => option.value === format),
  );
}

/** Empty serialized documents; consumer bindings still validate their SDK schema. */
export function productBlankDocument(
  action?: IntegrationAction,
  integrationId?: string,
): IntegrationDocument {
  const format = productDocumentFormats(action)[0] ?? "json";
  const json =
    integrationId === "lexical"
      ? {
          root: {
            children: [
              {
                children: [],
                direction: null,
                format: "",
                indent: 0,
                type: "paragraph",
                version: 1,
                textFormat: 0,
                textStyle: "",
              },
            ],
            direction: null,
            format: "",
            indent: 0,
            type: "root",
            version: 1,
          },
        }
      : integrationId === "blocknote"
        ? [{ type: "paragraph", props: {}, content: [], children: [] }]
        : {};
  return {
    id: "",
    title: "",
    content: format === "json" ? JSON.stringify(json, null, 2) : "",
    format,
    revision: 0,
    updatedAt: "",
  };
}

"use client";

import { useRef, useState, type ReactNode } from "react";
import { Bold, Heading2, List, Plus, RefreshCw, Save } from "lucide-react";
import { useLanguage } from "@/hooks/use-language";
import { useIntegrationOperation } from "@/hooks/use-integration-operation";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import type {
  IntegrationDocument,
  IntegrationValues,
  IntegrationWorkbenchProps,
} from "@/lib/integrations/contracts";
import {
  findProductAction,
  invalidProductField,
  productActionValues,
} from "./product-model";
import {
  ProductActionUnavailable,
  ProductDate,
  ProductDocumentPreview,
  ProductFields,
  ProductOperationFeedback,
  ProductPanel,
  ProductRecordList,
  ProductResourcePicker,
  ProductResult,
