export type ProductDocumentEditorProps = {
  value: IntegrationDocument;
  onChange: (
    value: Pick<IntegrationDocument, "title" | "content" | "format">,
  ) => void;
  disabled: boolean;
  locale: "en" | "es";
};
export type ProductEditorRenderer = (
  props: ProductDocumentEditorProps,
) => ReactNode;

export function ProductDocumentWorkbench(
  props: IntegrationWorkbenchProps & { renderEditor?: ProductEditorRenderer },
) {
  const { l, locale } = useLanguage();
  const read = useIntegrationOperation(props);
  const write = useIntegrationOperation(props);
  const resources = useProductResources(props);
  const queryAction = findProductAction(props.definition, "query");
  const saveAction = findProductAction(props.definition, "save-document");
  const [resourceId, setResourceId] = useState(
    props.connection.resourceIds[0] ?? "",
  );
  const [documentId, setDocumentId] = useState(
    props.connection.resourceIds[0] ?? "",
  );
  const [base, setBase] = useState<IntegrationDocument | null>(null);
  const [draft, setDraft] = useState<IntegrationDocument>(() =>
    productBlankDocument(saveAction, props.definition.id),
  );
  const [remote, setRemote] = useState<IntegrationDocument | null>(null);
  const [readValues, setReadValues] = useState<IntegrationValues>({});
  const [extra, setExtra] = useState<IntegrationValues>({});
  const [review, setReview] = useState<IntegrationValues | null>(null);
  const editor = useRef<HTMLTextAreaElement>(null);
  const dirty =
    !base ||
    ["title", "content", "format"].some(
      (key) =>
        draft[key as "title" | "content" | "format"] !==
        base[key as "title" | "content" | "format"],
    );
  let validJson = true;
  if (draft.format === "json") {
    try {
      JSON.parse(draft.content);
    } catch {
      validJson = false;
    }
  }
  const saveValues = productActionValues(
    saveAction,
    {
      ...extra,
      documentId: draft.id || documentId,
      id: draft.id || documentId,
      title: draft.title,
      content: draft.content,
      format: draft.format,
      revision: base?.revision ?? 0,
      expectedRevision: base?.revision ?? 0,
    },
    resourceId,
  );
  const blocked = write.pending || read.pending;

  function accept(document: IntegrationDocument) {
    setBase(document);
    setDraft(document);
    setDocumentId(document.id);
    setRemote(null);
    setReview(null);
    write.reset();
  }
  async function load(id = documentId) {
    if (!queryAction) return;
    const values = productActionValues(
      queryAction,
      { ...readValues, documentId: id, id, view: "document" },
      resourceId,
    );
    if (invalidProductField(queryAction, values)) return;
    const result = await read.run(queryAction, values);
    if (result?.kind === "document") {
      if (
        base?.id === result.document.id &&
        result.document.revision < base.revision
      )
        return;
      if (base && dirty) setRemote(result.document);
      else accept(result.document);
    }
  }
  function change(
    value: Pick<IntegrationDocument, "title" | "content" | "format">,
  ) {
    setDraft((previous) => ({ ...previous, ...value }));
    setReview(null);
  }
  function insert(prefix: string, suffix = "") {
    const start = editor.current?.selectionStart ?? draft.content.length;
    const end = editor.current?.selectionEnd ?? start;
    change({
      ...draft,
      content: `${draft.content.slice(0, start)}${prefix}${draft.content.slice(start, end)}${suffix}${draft.content.slice(end)}`,
    });
    requestAnimationFrame(() => {
      editor.current?.focus();
      editor.current?.setSelectionRange(
        start + prefix.length,
        end + prefix.length,
      );
    });
  }
  async function save() {
    if (!saveAction || !review) return;
    const result = await write.run(saveAction, review);
    if (result?.kind === "document") accept(result.document);
    else if (result) setReview(null);
  }

  return (
    <div className="space-y-5">
      <ProductPanel
        title={l("Document workspace", "Espacio de documentos")}
        description={l(
          "Edit Markdown, text or structured documents with a versioned save.",
          "Edita Markdown, texto o documentos estructurados con guardado por versión.",
        )}
      >
        <div className="grid gap-4 sm:grid-cols-2">
          <ProductResourcePicker
            {...resources}
            value={resourceId}
            onChange={(value) => {
              setResourceId(value);
              setDocumentId(value);
              setBase(null);
              setDraft(productBlankDocument(saveAction, props.definition.id));
              read.reset();
              write.reset();
              setRemote(null);
              setReview(null);
            }}
            disabled={blocked || Boolean(base && dirty)}
          />
          <label className="space-y-2 text-xs font-medium">
            {l("Document ID", "ID del documento")}
            <Input
              value={documentId}
              onChange={(event) => {
                setDocumentId(event.target.value);
                setReview(null);
              }}
              disabled={blocked}
              placeholder={l(
                "Open an existing document",
                "Abrir un documento existente",
              )}
            />
          </label>
        </div>
        <div className="mt-4">
          <ProductFields
            action={queryAction}
            values={readValues}
            onChange={setReadValues}
            exclude={["resourceId", "id", "documentId"]}
            disabled={blocked}
          />
        </div>
        <div className="my-4 flex flex-wrap gap-2">
          <Button
            variant="outline"
            loading={read.pending}
            disabled={!queryAction || write.pending}
            onClick={() => {
              void load();
            }}
          >
            <RefreshCw />
            {l("Load document", "Cargar documento")}
          </Button>
          <Button
            variant="outline"
            disabled={blocked || Boolean(base && dirty)}
            onClick={() => {
              setBase(null);
              setDraft(productBlankDocument(saveAction, props.definition.id));
              setDocumentId("");
              setRemote(null);
              setReview(null);
              write.reset();
            }}
          >
            <Plus />
            {l("New document", "Nuevo documento")}
          </Button>
          {base && (
            <p className="self-center text-[11px] text-muted-foreground">
              {l("Revision", "Revisión")} {base.revision} ·{" "}
              <ProductDate value={base.updatedAt} />
            </p>
          )}
        </div>
        <ProductActionUnavailable action={queryAction} />
        <ProductOperationFeedback operation={read} />
        {read.result?.kind === "records" && (
          <ProductRecordList
            records={read.result.records}
            onSelect={(record) => {
              setDocumentId(record.id);
              void load(record.id);
            }}
            selected={base?.id}
          />
        )}
      </ProductPanel>
      <div className="grid items-start gap-5 xl:grid-cols-2">
        <ProductPanel
          title={l("Editor", "Editor")}
          description={
            dirty
              ? l("Unsaved changes", "Cambios sin guardar")
              : l(
                  "Matches the stored revision",
                  "Coincide con la versión guardada",
                )
          }
        >
          {props.renderEditor ? (
            props.renderEditor({
              value: draft,
              onChange: change,
              disabled: blocked,
              locale,
            })
          ) : (
            <div className="space-y-4">
              <label className="block space-y-2 text-xs font-medium">
                {l("Title", "Título")}
                <Input
                  value={draft.title}
                  onChange={(event) =>
                    change({ ...draft, title: event.target.value })
                  }
                  disabled={blocked}
                />
              </label>
              <Select
                label={l("Document format", "Formato del documento")}
                value={draft.format}
                onValueChange={(value) =>
                  change({
                    ...draft,
                    format: value as IntegrationDocument["format"],
                  })
                }
                options={[
                  { value: "markdown", label: "Markdown" },
                  { value: "text", label: l("Plain text", "Texto") },
                  {
                    value: "json",
                    label: l("Structured JSON", "JSON estructurado"),
                  },
                ].filter((option) =>
                  productDocumentFormats(saveAction).includes(
                    option.value as IntegrationDocument["format"],
                  ),
                )}
                disabled={blocked}
              />
              {draft.format === "markdown" && (
                <div
                  role="toolbar"
                  aria-label={l("Formatting", "Formato")}
                  className="flex flex-wrap gap-2"
                >
                  <Button
                    size="sm"
                    variant="outline"
                    aria-label={l("Bold", "Negrita")}
                    disabled={blocked}
                    onClick={() => insert("**", "**")}
                  >
                    <Bold />
                  </Button>
                  <Button
                    size="sm"
                    variant="outline"
                    aria-label={l("Heading", "Encabezado")}
                    disabled={blocked}
                    onClick={() => insert("\n## ")}
                  >
                    <Heading2 />
                  </Button>
                  <Button
                    size="sm"
                    variant="outline"
                    aria-label={l("List item", "Elemento de lista")}
                    disabled={blocked}
                    onClick={() => insert("\n- ")}
                  >
                    <List />
                  </Button>
                </div>
              )}
              <label className="block space-y-2 text-xs font-medium">
                {l("Document content", "Contenido del documento")}
                <Textarea
                  ref={editor}
                  value={draft.content}
                  onChange={(event) =>
                    change({ ...draft, content: event.target.value })
                  }
                  className="min-h-72 font-mono text-xs"
                  disabled={blocked}
                  aria-invalid={!validJson}
                  spellCheck={draft.format !== "json"}
                />
              </label>
            </div>
          )}
          {!validJson && (
            <p
              role="alert"
              className="mt-3 text-xs text-destructive-foreground"
            >
              {l(
                "Correct the JSON syntax before saving.",
                "Corrige la sintaxis JSON antes de guardar.",
              )}
            </p>
          )}
          <div className="my-4">
            <ProductFields
              action={saveAction}
              values={extra}
              onChange={(value) => {
                setExtra(value);
                setReview(null);
              }}
              exclude={[
                "resourceId",
                "id",
                "documentId",
                "title",
                "content",
                "format",
                "revision",
                "expectedRevision",
              ]}
              disabled={blocked}
            />
          </div>
          <ProductValidation action={saveAction} values={saveValues} />
          <div className="mt-4 flex flex-wrap gap-2">
            <Button
              appearance="gradient"
              disabled={
                !saveAction ||
                blocked ||
                !draft.title.trim() ||
                !validJson ||
                Boolean(invalidProductField(saveAction, saveValues)) ||
                write.errorCode === "conflict"
              }
              onClick={() => setReview(saveValues)}
            >
              <Save />
              {l("Review and save", "Revisar y guardar")}
            </Button>
            {base && (
              <Button
                variant="outline"
                disabled={blocked}
                onClick={() => accept(base)}
              >
                {l("Discard local changes", "Descartar cambios locales")}
              </Button>
            )}
          </div>
          <div className="mt-4">
            <ProductActionUnavailable action={saveAction} />
            <ProductOperationFeedback operation={write} />
          </div>
          {write.result && write.result.kind !== "document" && (
            <div className="mt-4">
              <ProductResult result={write.result} />
              <p className="mt-2 text-xs text-muted-foreground">
                {l(
                  "Reload to confirm the stored document revision.",
                  "Recarga para confirmar la versión del documento guardado.",
                )}
              </p>
            </div>
          )}
        </ProductPanel>
        <ProductPanel title={l("Preview", "Vista previa")}>
          <ProductDocumentPreview
            content={draft.content}
            format={draft.format}
          />
        </ProductPanel>
      </div>
      {(remote || write.errorCode === "conflict") && (
        <ProductPanel
          title={l(
            "Resolve a document conflict",
            "Resolver un conflicto de documento",
          )}
        >
          <p className="mb-4 text-xs leading-6">
            {l(
              "Your edits are preserved. Load the latest revision and compare it before choosing which version to keep.",
              "Tus cambios se conservan. Carga la versión actual y compárala antes de elegir qué versión conservar.",
            )}
          </p>
          {remote && (
            <div className="mb-4">
              <p className="mb-3 text-xs font-medium">
                {remote.title} · {l("Revision", "Revisión")} {remote.revision}
              </p>
              <ProductDocumentPreview
                content={remote.content}
                format={remote.format}
              />
            </div>
          )}
          <div className="flex flex-wrap gap-2">
            <Button
              variant="outline"
              loading={read.pending}
              onClick={() => {
                void load(base?.id ?? documentId);
              }}
            >
              {l("Load latest revision", "Cargar versión actual")}
            </Button>
            {remote && (
              <>
                <Button variant="outline" onClick={() => accept(remote)}>
                  {l("Use remote content", "Usar contenido remoto")}
                </Button>
                <Button
                  appearance="gradient"
                  onClick={() => {
                    setBase(remote);
                    setDraft((value) => ({
                      ...value,
                      id: remote.id,
                      revision: remote.revision,
                    }));
                    setDocumentId(remote.id);
                    setRemote(null);
                    setReview(null);
                    write.reset();
                  }}
                >
                  {l(
                    "Keep edits, use latest revision",
                    "Conservar cambios y usar revisión actual",
                  )}
                </Button>
              </>
            )}
          </div>
        </ProductPanel>
      )}
      {review && saveAction && (
        <ProductReview
          action={saveAction}
          values={review}
          pending={write.pending}
          grantedPermissions={props.connection.grantedPermissions}
          onConfirm={() => {
            void save();
          }}
          onReject={() => setReview(null)}
        />
      )}
    </div>
  );
}

import type {
  IntegrationAction,
  IntegrationDefinition,
  IntegrationField,
  IntegrationOperationKind,
  IntegrationRecord,
  IntegrationResult,
  IntegrationValues,
  IntegrationWorkbenchProps,
} from "../../lib/integrations/contracts";
import type { DataTableQuery } from "../../lib/data-query";

export function findProductAction(
  definition: IntegrationDefinition,
  ...kinds: IntegrationOperationKind[]
) {
  for (const kind of kinds) {
    const action = definition.actions.find((item) => item.kind === kind);
    if (action) return action;
  }
  return undefined;
}

/** A configuration or permission change discards drafts tied to the old scope. */
export function productScopeKey({
  definition,
  connection,
  scope,
  adapter,
}: IntegrationWorkbenchProps) {
  return JSON.stringify([
    adapter.mode,
    definition.id,
    connection.id,
    connection.providerOptionId,
    connection.workspaceId,
    scope.workspaceId,
    connection.revision,
    connection.status,
    [...connection.resourceIds].sort(),
    [...connection.grantedPermissions].sort(),
  ]);
}

export function defaultActionValues(
  action?: IntegrationAction,
): IntegrationValues {
  return Object.fromEntries(
    (action?.fields ?? []).map((field) => [
      field.id,
      field.type === "toggle"
        ? false
        : field.type === "select"
          ? (field.options?.[0]?.value ?? "")
          : "",
    ]),
  );
}

/** A create recipe must never reuse the selected source record as its target. */
export function productRecordNeedsTarget(action?: IntegrationAction) {
  return (
    action?.kind === "update-record" ||
    (action?.kind === "save-record" &&
      action.fields.some(
        (field) => ["recordId", "id"].includes(field.id) && field.required,
      ))
  );
}

/** Demo reads can start immediately; consumer references remain explicit inputs. */
export function productReadDefaults(
  action: IntegrationAction | undefined,
  props: IntegrationWorkbenchProps,
): IntegrationValues {
  const values = defaultActionValues(action);
  if (props.adapter.mode !== "demo") return values;
  const start = new Date();
  start.setUTCHours(0, 0, 0, 0);
  const end = new Date(start.getTime() + 7 * 24 * 60 * 60 * 1000);
  for (const field of action?.fields ?? []) {
    if (!field.required || field.type !== "text") continue;
    if (field.id === "startAt") values[field.id] = start.toISOString();
    else if (field.id === "endAt") values[field.id] = end.toISOString();
    else if (/(?:Id|Ref)$/.test(field.id))
      values[field.id] = props.connection.resourceIds[0] ?? "";
  }
  return values;
}

const resourceFields = new Set([
  "resourceId",
  "resource",
  "sourceId",
  "collectionId",
  "tableId",
  "indexId",
  "channelId",
  "repositoryId",
  "projectId",
  "databaseId",
  "siteId",
]);

/** Explicit values win. A resource binding is always a consumer-authorized ID. */
export function productActionValues(
  action: IntegrationAction | undefined,
  values: IntegrationValues,
  resourceId = "",
): IntegrationValues {
  const output = { ...defaultActionValues(action), ...values };
  if (resourceId) {
    output.resourceId = resourceId;
    for (const field of action?.fields ?? []) {
      if (resourceFields.has(field.id) && !output[field.id]) {
        output[field.id] = resourceId;
      }
    }
  }
  return output;
}

export function invalidProductField(
  action: Pick<IntegrationAction, "fields"> | undefined,
  values: IntegrationValues,
): IntegrationField | undefined {
  return action?.fields.find((field) => {
    const value = values[field.id];
    const empty =
      value === undefined ||
      (typeof value === "string" && !value.trim()) ||
      (Array.isArray(value) && value.length === 0);
    if (empty) return field.required === true;
    if (field.type === "number") {
      return !Number.isFinite(
        typeof value === "number" ? value : Number(value),
      );
    }
    if (field.type === "toggle") return typeof value !== "boolean";
    if (field.type === "select") {
      return !field.options?.some((option) => option.value === value);
    }
    return false;
  });
}

export function parseProductArguments(
  source: string,
): { ok: true; json: string } | { ok: false } {
  function valid(value: unknown, depth = 0): boolean {
    if (depth > 20) return false;
    if (
      value === null ||
      typeof value === "string" ||
      typeof value === "boolean"
    )
      return true;
    if (typeof value === "number") return Number.isFinite(value);
    if (Array.isArray(value))
      return value.every((item) => valid(item, depth + 1));
    if (!value || typeof value !== "object") return false;
    return Object.entries(value).every(
      ([key, item]) =>
        !["__proto__", "constructor", "prototype"].includes(key) &&
        valid(item, depth + 1),
    );
  }
  try {
    const value = JSON.parse(source);
    if (
      !value ||
      typeof value !== "object" ||
      Array.isArray(value) ||
      !valid(value)
    )
      return { ok: false };
    return { ok: true, json: JSON.stringify(value) };
  } catch {
    return { ok: false };
  }
}

/** The backend applies filters/sorting/page boundaries; the UI never re-pages results. */
export function productQueryValues(
  query: DataTableQuery,
  resourceId = "",
): IntegrationValues {
  const sort = query.sorting[0];
  const status = query.filters.find((filter) => filter.id === "status");
  const filterValue = status?.value;
  return {
    resourceId,
    query: query.search,
    search: query.search,
    filter: typeof filterValue === "string" ? filterValue : "",
    status: typeof filterValue === "string" ? filterValue : "",
    page: query.pagination.pageIndex,
    pageNumber: query.pagination.pageIndex + 1,
    pageIndex: query.pagination.pageIndex,
    pageSize: query.pagination.pageSize,
    limit: query.pagination.pageSize,
    offset: query.pagination.pageIndex * query.pagination.pageSize,
    sort: sort?.id ?? "",
    order: sort?.desc ? "desc" : "asc",
    direction: sort?.desc ? "desc" : "asc",
    filters: JSON.stringify(query.filters),
    sorting: JSON.stringify(query.sorting),
    queryState: JSON.stringify(query),
  };
}

export function mergeProductRecords(
  previous: readonly IntegrationRecord[],
  incoming: readonly IntegrationRecord[],
) {
  const records = new Map(previous.map((record) => [record.id, record]));
  for (const record of incoming) {
    if (!record.id) continue;
    const current = records.get(record.id);
    if (
      current &&
      Number.isFinite(Date.parse(current.updatedAt)) &&
      Number.isFinite(Date.parse(record.updatedAt)) &&
      Date.parse(record.updatedAt) < Date.parse(current.updatedAt)
    ) {
      continue;
    }
    records.set(record.id, record);
  }
  return [...records.values()];
}

export function optimisticProductRecord(
  record: IntegrationRecord,
  values: IntegrationValues,
  marker: string,
): IntegrationRecord {
  return {
    ...record,
    name: typeof values.name === "string" ? values.name : record.name,
    description:
      typeof values.description === "string"
        ? values.description
        : record.description,
    status: typeof values.status === "string" ? values.status : record.status,
    updatedAt: marker,
  };
}

/** Roll back only this mutation, never a newer query or another acknowledged write. */
export function rollbackProductRecord(
  records: readonly IntegrationRecord[],
  original: IntegrationRecord,
  marker: string,
) {
  return records.map((record) =>
    record.id === original.id && record.updatedAt === marker
      ? original
      : record,
  );
}

export function parseProductFields(
  source: string,
):
  | { ok: true; values: IntegrationValues }
  | { ok: false; reason: "json" | "values" } {
  let value: unknown;
  try {
    value = JSON.parse(source);
  } catch {
    return { ok: false, reason: "json" };
  }
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return { ok: false, reason: "values" };
  }
  const entries = Object.entries(value);
  if (
    entries.some(
      ([key, item]) =>
        ["__proto__", "constructor", "prototype"].includes(key) ||
        !(
          typeof item === "string" ||
          typeof item === "boolean" ||
          (typeof item === "number" && Number.isFinite(item)) ||
          (Array.isArray(item) &&
            item.every((part) => typeof part === "string"))
        ),
    )
  ) {
    return { ok: false, reason: "values" };
  }
  return { ok: true, values: Object.fromEntries(entries) };
}

export function safeProductUrl(value?: string) {
  if (!value) return undefined;
  if (
    value.startsWith("/") &&
    !value.startsWith("//") &&
    !value.includes("\\")
  ) {
    return value;
  }
  try {
    const url = new URL(value);
    return ["https:", "http:"].includes(url.protocol) &&
      !url.username &&
      !url.password
      ? url.href
      : undefined;
  } catch {
    return undefined;
  }
}

export function productSearchSegments(text: string, query: string) {
  const term = query.trim();
  if (!term) return [{ text, match: false }];
  const escaped = term.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return text
    .split(new RegExp(`(${escaped})`, "ig"))
    .filter(Boolean)
    .map((part) => ({
      text: part,
      match: part.toLocaleLowerCase() === term.toLocaleLowerCase(),
    }));
}

export function productMapLocations(
  result: Extract<IntegrationResult, { kind: "map" }>,
) {
  const seen = new Set<string>();
  return result.locations.filter((location) => {
    if (
      !location.id ||
      seen.has(location.id) ||
      !Number.isFinite(location.latitude) ||
      !Number.isFinite(location.longitude) ||
      Math.abs(location.latitude) > 90 ||
      Math.abs(location.longitude) > 180
    ) {
      return false;
    }
    seen.add(location.id);
    return true;
  });
}

export type ProductFieldMapping = { source: string; target: string };
export function validProductMapping(mapping: readonly ProductFieldMapping[]) {
  const targets = new Set<string>();
  return (
    mapping.length > 0 &&
    mapping.every(({ source, target }) => {
      if (
        !source.trim() ||
        !target.trim() ||
        targets.has(target) ||
        ["__proto__", "constructor", "prototype"].includes(target)
      ) {
        return false;
      }
      targets.add(target);
      return true;
    })
  );
}

export function mapProductRecord(
  record: IntegrationRecord,
  mapping: readonly ProductFieldMapping[],
): IntegrationValues {
  const fields: IntegrationValues = {
    ...record.fields,
    id: record.id,
    name: record.name,
    title: record.name,
    status: record.status,
    description: record.description,
    type: record.type,
    updatedAt: record.updatedAt,
  };
  return Object.fromEntries(
    mapping
      .filter(
        ({ source, target }) =>
          source in fields &&
          !["__proto__", "constructor", "prototype"].includes(target),
      )
      .map(({ source, target }) => [target, fields[source]]),
  );
}

/** Only declarative primitive input fields are read; schema code is never evaluated. */
export function productToolFields(
  record?: IntegrationRecord,
): IntegrationField[] {
  const source = record?.fields?.inputSchema ?? record?.fields?.schema;
  if (typeof source !== "string" || source.length > 50_000) return [];
  try {
    const schema = JSON.parse(source);
    if (
      !schema ||
      typeof schema !== "object" ||
      !schema.properties ||
      typeof schema.properties !== "object"
    )
      return [];
    const required = new Set(
      Array.isArray(schema.required) ? schema.required : [],
    );
    return Object.entries(schema.properties)
      .filter(([id]) => !["__proto__", "constructor", "prototype"].includes(id))
      .flatMap(([id, value]) => {
        if (!value || typeof value !== "object") return [];
        const property = value as {
          title?: string;
          description?: string;
          type?: string;
          enum?: unknown[];
        };
        if (
          !["string", "number", "integer", "boolean"].includes(
            property.type ?? "",
          )
        )
          return [];
        const title = typeof property.title === "string" ? property.title : id;
        const options = Array.isArray(property.enum)
          ? property.enum
              .filter((item): item is string => typeof item === "string")
              .map((item) => ({ value: item, label: { en: item, es: item } }))
          : [];
        return [
          {
            id,
            label: { en: title, es: title },
            description:
              typeof property.description === "string"
                ? { en: property.description, es: property.description }
                : undefined,
            type: options.length
              ? "select"
              : property.type === "boolean"
                ? "toggle"
                : ["number", "integer"].includes(property.type ?? "")
                  ? "number"
                  : "text",
            options: options.length ? options : undefined,
            required: required.has(id),
          } satisfies IntegrationField,
        ];
      });
  } catch {
    return [];
  }
}

import type { IntegrationUpdate } from "../../lib/integrations/contracts";

export type ProductSubscriptionStarter<Update = IntegrationUpdate> = (
  listener: (update: Update) => void,
  signal: AbortSignal,
) => (() => void) | Promise<() => void>;

/** Handles asynchronous transport setup, aborts, and cleanup arriving after unmount. */
export function startProductSubscription<Update = IntegrationUpdate>(
  starter: ProductSubscriptionStarter<Update>,
  options: {
    signal?: AbortSignal;
    onUpdate: (update: Update) => void;
    onError: () => void;
  },
) {
  const controller = new AbortController();
  let active = true;
  let cleanup: (() => void) | undefined;
  const dispose = () => {
    if (!active) return;
    active = false;
    controller.abort();
    options.signal?.removeEventListener("abort", dispose);
    const current = cleanup;
    cleanup = undefined;
    try {
      current?.();
    } catch {
      // An unavailable consumer transport must not prevent the abort or unmount.
    }
  };
  if (options.signal?.aborted) {
    dispose();
    return dispose;
  }
  options.signal?.addEventListener("abort", dispose, { once: true });
  try {
    Promise.resolve(
      starter((update) => {
        if (active && !controller.signal.aborted) options.onUpdate(update);
      }, controller.signal),
    )
      .then((unsubscribe) => {
        if (active && !controller.signal.aborted) cleanup = unsubscribe;
        else unsubscribe();
      })
      .catch(() => {
        if (active && !controller.signal.aborted) options.onError();
      });
  } catch {
    if (active && !controller.signal.aborted) options.onError();
  }
  return dispose;
}

