export function ProductFields({
  action,
  fields = action?.fields ?? [],
  values,
  onChange,
  exclude = [],
  disabled,
}: {
  action?: IntegrationAction;
  fields?: readonly IntegrationField[];
  values: IntegrationValues;
  onChange: (values: IntegrationValues) => void;
  exclude?: readonly string[];
  disabled?: boolean;
}) {
  const { l } = useLanguage();
  const id = useId();
  return (
    <div className="grid gap-4 sm:grid-cols-2">
      {fields
        .filter((field) => !exclude.includes(field.id))
        .map((field) => {
          const inputId = `${id}-${field.id}`;
          const descriptionId = `${inputId}-description`;
          const value = values[field.id];
          const label = l(field.label.en, field.label.es);
          const change = (next: string | number | boolean) =>
            onChange({ ...values, [field.id]: next });
          return (
            <div key={field.id} className="min-w-0 space-y-1.5">
              <label htmlFor={inputId} className="block text-xs font-medium">
                {label}
                {field.required && <span aria-hidden="true"> *</span>}
              </label>
              {field.type === "toggle" ? (
                <div className="flex min-h-10 items-center gap-2">
                  <Checkbox
                    id={inputId}
                    checked={value === true}
                    onCheckedChange={change}
                    disabled={disabled}
                    aria-describedby={
                      field.description ? descriptionId : undefined
                    }
                  />
                  <span className="text-xs text-muted-foreground">
                    {value === true
                      ? l("Enabled", "Activado")
                      : l("Disabled", "Desactivado")}
                  </span>
                </div>
              ) : field.type === "select" ? (
                <Select
                  id={inputId}
                  aria-label={label}
                  value={
                    typeof value === "string"
                      ? value
                      : (field.options?.[0]?.value ?? "")
                  }
                  options={(field.options ?? []).map((option) => ({
                    value: option.value,
                    label: l(option.label.en, option.label.es),
                  }))}
                  onValueChange={change}
                  disabled={disabled}
                  aria-describedby={
                    field.description ? descriptionId : undefined
                  }
                />
              ) : (
                <Input
                  id={inputId}
                  type={
                    field.type === "number"
                      ? "number"
                      : field.type === "url"
                        ? "url"
                        : "text"
                  }
                  step={field.type === "number" ? "any" : undefined}
                  value={
                    typeof value === "string" || typeof value === "number"
                      ? value
                      : ""
                  }
                  placeholder={field.placeholder}
                  required={field.required}
                  disabled={disabled}
                  aria-describedby={
                    field.description ? descriptionId : undefined
                  }
                  onChange={(event) =>
                    change(
                      field.type === "number" && event.target.value !== ""
                        ? Number(event.target.value)
                        : event.target.value,
                    )
                  }
                />
              )}
              {field.description && (
                <p
                  id={descriptionId}
                  className="text-[11px] leading-5 text-muted-foreground"
                >
                  {l(field.description.en, field.description.es)}
                </p>
              )}
            </div>
          );
        })}
    </div>
  );
}

