          <Check />
          {l("Confirm action", "Confirmar acción")}
        </Button>
        <Button variant="outline" disabled={pending} onClick={onReject}>
          {l("Back to editing", "Volver a editar")}
        </Button>
      </div>
    </ProductPanel>
  );
