          label: resource.name,
        }))}
        placeholder={
          pending
            ? l("Loading resources…", "Cargando recursos…")
            : l("Choose a resource", "Elige un recurso")
        }
        onValueChange={onChange}
        disabled={disabled || pending || resources.length === 0}
