        </div>
      ))}
      {entries.length > 50 && (
        <p className="text-xs text-muted-foreground">
          {l(
            "Preview shows the first 50 entries.",
            "La vista previa muestra las primeras 50 entradas.",
          )}
        </p>
      )}
    </dl>
  );
}

export function ProductDocumentPreview({
