export type AuthHttpAdapterOptions = {
  /** Same-origin absolute path, e.g. /api/identity. No query, fragment or URL. */
  basePath: string;
  providerId?: string;
  /** Optional for browser use; required when invoking from non-browser tests. */
  origin?: string;
  redirectPolicy?: AuthRedirectPolicy;
  fetch?: typeof globalThis.fetch;
  /** Ephemeral anti-CSRF value from your app, never a provider key/bearer token. */
  csrfToken?: () => string | undefined | Promise<string | undefined>;
};
function transportOrigin(origin?: string): string {
  const browserOrigin =
    typeof window !== "undefined" ? window.location.origin : undefined;
  const configured = configuredOrigin(origin ?? browserOrigin ?? "");
  if (browserOrigin && configured !== browserOrigin)
    throw new AuthWorkflowError("unsafe-url");
  return configured;
}
function errorForStatus(
  status: number,
  operation: AuthWorkflowOperation,
): AuthWorkflowErrorCode {
  if (status === 400 || status === 422) return "invalid-request";
  if (status === 401)
    return operation === "signIn" ? "invalid-credentials" : "unauthorized";
  if (status === 403) return "forbidden";
  if (status === 404 || status === 405 || status === 501) return "unsupported";
  if (status === 409) return "conflict";
  if (status === 410) return "expired";
  if (status === 429) return "rate-limited";
  return "network";
}
async function responseJson(response: Response): Promise<unknown> {
  if (
    !/^application\/(?:json|[a-z0-9.+-]+\+json)(?:\s*;|$)/i.test(
      response.headers.get("content-type") ?? "",
    )
  ) {
    throw new AuthWorkflowError("invalid-response");
  }
  const limit = 2_000_000;
  if (Number(response.headers.get("content-length")) > limit)
    throw new AuthWorkflowError("invalid-response");
  const reader = response.body?.getReader();
  if (!reader) throw new AuthWorkflowError("invalid-response");
  const decoder = new TextDecoder();
  let text = "",
    size = 0;
  try {
    while (true) {
      const { value, done } = await reader.read();
      if (done) break;
      size += value.byteLength;
      if (size > limit) throw new AuthWorkflowError("invalid-response");
      text += decoder.decode(value, { stream: true });
    }
    text += decoder.decode();
    return JSON.parse(text) as unknown;
  } catch {
    await reader.cancel().catch(() => {});
    throw new AuthWorkflowError("invalid-response");
  } finally {
    reader.releaseLock();
  }
}
export function createAuthHttpAdapter(
  options: AuthHttpAdapterOptions,
): AuthWorkflowAdapter {
  const { basePath } = options;
  if (!safePath(basePath) || /[?#]/.test(basePath) || basePath === "/") {
    throw new AuthWorkflowError("unsafe-url");
  }
  if (options.origin) configuredOrigin(options.origin);
  const handlers = {} as Record<
    AuthWorkflowOperation,
    (
      request: AuthWorkflowRequests[AuthWorkflowOperation],
      scope: AuthWorkflowScope,
    ) => unknown | Promise<unknown>
  >;
  for (const operation of Object.keys(
    AUTH_WORKFLOW_ENDPOINTS,
  ) as AuthWorkflowOperation[]) {
    handlers[operation] = async (request, scope) => {
      const origin = transportOrigin(options.origin);
      const url = new URL(
        `${basePath.replace(/\/$/, "")}/${AUTH_WORKFLOW_ENDPOINTS[operation]}`,
        origin,
      );
      const csrf = await options.csrfToken?.();
      checkAbort(scope.signal);
      if (
        csrf !== undefined &&
        (typeof csrf !== "string" ||
          !csrf.length ||
          csrf.length > 1024 ||
          /[\u0000-\u0020\u007f]/.test(csrf))
      ) {
        throw new AuthWorkflowError("invalid-request");
      }
      const headers: Record<string, string> = {
        Accept: "application/json",
        "Content-Type": "application/json",
      };
      if (csrf) headers["X-CSRF-Token"] = csrf;
      const response = await (options.fetch ?? globalThis.fetch)(url.href, {
        method: "POST",
        headers,
        body: JSON.stringify(request),
        credentials: "same-origin",
        cache: "no-store",
        redirect: "error",
        signal: scope.signal,
      });
      checkAbort(scope.signal);
      if (
        response.redirected ||
        (response.url && new URL(response.url).origin !== origin)
      ) {
        throw new AuthWorkflowError("unsafe-url");
      }
      if (!response.ok) {
        let code = errorForStatus(response.status, operation);
        let retryAfterSeconds: number | undefined;
        try {
          const body = await responseJson(response);
          const parsed = z
            .object({
              error: z.object({
                code: z.enum(AUTH_WORKFLOW_ERROR_CODES),
                retryAfterSeconds: z
                  .number()
                  .int()
                  .min(0)
                  .max(86400)
                  .optional(),
              }),
            })
            .safeParse(body);
          if (parsed.success) ({ code, retryAfterSeconds } = parsed.data.error);
        } catch {
          /* Never expose provider/HTML error bodies. */
        }
        checkAbort(scope.signal);
        throw new AuthWorkflowError(code, retryAfterSeconds);
      }
      return await responseJson(response);
    };
  }
  return makeAdapter(
    "consumer",
    options.providerId ?? "consumer",
    handlers,
    options.redirectPolicy,
  );
}

type MockOrganization = {
  organization: AuthOrganization;
  members: AuthMember[];
  invitations: AuthInvitation[];
};
const OK: AuthActionResult = { kind: "ok" };
export type MockAuthWorkflowOptions = {
  delayMs?: number;
  signedIn?: boolean;
  providerId?: string;
};
/** Stateful, memory-only preview. It accepts demo passwords; it authenticates nobody. */
export function createMockAuthWorkflowAdapter({
  delayMs = 250,
  signedIn = true,
  providerId = "mock",
}: MockAuthWorkflowOptions = {}): AuthWorkflowAdapter {
  if (!Number.isFinite(delayMs) || delayMs < 0 || delayMs > 10000)
    throw new AuthWorkflowError("invalid-request");
  let serial = 0;
  const nextId = (prefix: string) => `demo-${prefix}-${++serial}`;
  const now = () => new Date().toISOString();
  const later = (days = 7) =>
    new Date(Date.now() + days * 86400000).toISOString();
  let user: AuthUser = {
    id: "demo-user",
    name: "Alex Morgan",
    email: "alex.morgan@example.com",
    emailVerified: true,
  };
  const newSession = (): AuthSession => ({
    id: nextId("session"),
    user: { ...user },
    createdAt: now(),
    expiresAt: later(),
  });
  let session: AuthSession | null = signedIn ? newSession() : null;
  const device = (value: AuthSession): AuthDeviceSession => ({
    id: value.id,
    device: "Chrome · This browser",
    location: "Local preview",
    createdAt: value.createdAt,
    lastActiveAt: now(),
    expiresAt: value.expiresAt,
    current: true,
  });
  let sessions: AuthDeviceSession[] = session
    ? [
        device(session),
        {
          id: "demo-session-laptop",
          device: "Safari · MacBook",
          location: "Local preview",
          createdAt: now(),
          lastActiveAt: now(),
          expiresAt: later(),
          current: false,
        },
        {
          id: "demo-session-phone",
          device: "Chrome · Android",
          location: "Local preview",
          createdAt: now(),
          lastActiveAt: now(),
          expiresAt: later(),
          current: false,
        },
      ]
    : [];
  const organizations = new Map<string, MockOrganization>([
    [
      "demo-studio",
      {
        organization: {
          id: "demo-studio",
          name: "Aureform Studio",
          slug: "aureform-studio",
          role: "owner",
        },
        members: [
          { id: "demo-member-alex", user: { ...user }, role: "owner" },
          {
            id: "demo-member-sam",
            user: {
              id: "demo-user-sam",
              name: "Sam Rivera",
              email: "sam@example.com",
              emailVerified: true,
            },
            role: "admin",
          },
          {
            id: "demo-member-jordan",
            user: {
              id: "demo-user-jordan",
              name: "Jordan Lee",
              email: "jordan@example.com",
              emailVerified: true,
            },
            role: "member",
          },
        ],
        invitations: [
          {
            id: "demo-invitation-taylor",
            email: "taylor@example.com",
            role: "member",
            status: "pending",
            createdAt: now(),
            expiresAt: later(),
          },
        ],
      },
    ],
  ]);
  let activeOrganizationId: string | null = "demo-studio";
  const factors: AuthMfaFactor[] = [];
  const challenges = new Map<
    string,
    { kind: "email" | "mfa"; email: string; name: string }
  >();
  const enrollments = new Map<string, { label: string }>();
  const requireSession = () => {
    if (!session) throw new AuthWorkflowError("unauthorized");
    return session;
  };
  const organizationFor = (organizationId: string, manage = false) => {
    requireSession();
    const value = organizations.get(organizationId);
    if (!value) throw new AuthWorkflowError("forbidden");
    if (manage && value.organization.role === "member")
      throw new AuthWorkflowError("forbidden");
    return value;
  };
  const synchronizeUser = () => {
    if (session) session = { ...session, user: { ...user } };
    for (const entry of organizations.values()) {
      entry.members = entry.members.map((member) =>
        member.user.id === user.id ? { ...member, user: { ...user } } : member,
      );
    }
  };
  const establishSession = (): AuthFlowResult => {
    session = newSession();
    sessions = [device(session)];
    synchronizeUser();
    return { kind: "session", session: { ...session, user: { ...user } } };
  };
  const verifyDemoCode = (value: string, recovery = false) => {
    if (value !== "123456" && !(recovery && value === "DEMO-RECOVERY"))
      throw new AuthWorkflowError("invalid-code");
  };
  const identity = (): AuthIdentityState => {
    if (!session)
      return {
        session: null,
        organizations: [],
        activeOrganizationId: null,
        members: [],
        invitations: [],
        sessions: [],
        factors: [],
      };
    const active = activeOrganizationId
      ? organizations.get(activeOrganizationId)
      : undefined;
    return structuredClone({
      session,
      organizations: [...organizations.values()].map(
        (entry) => entry.organization,
      ),
      activeOrganizationId,
      members: active?.members ?? [],
      invitations: active?.invitations ?? [],
      sessions,
      factors,
    });
  };
  const handlers: AuthWorkflowHandlers = {
    signIn: (request) => {
      user = { ...user, email: request.email, emailVerified: true };
      if (factors.length) {
        const challengeId = nextId("mfa-challenge");
        challenges.set(challengeId, {
          kind: "mfa",
          email: user.email,
          name: user.name,
        });
        session = null;
        sessions = [];
        return {
          kind: "mfa-required",
          challengeId,
          factors: ["totp", "recovery-code"],
        };
      }
      return establishSession();
    },
    signUp: (request) => {
      user = {
        ...user,
        name: request.name,
        email: request.email,
        emailVerified: false,
      };
      session = null;
      sessions = [];
      const challengeId = nextId("email-challenge");
      challenges.set(challengeId, {
        kind: "email",
        email: request.email,
        name: request.name,
      });
      return {
        kind: "verification-required",
        challengeId,
        email: request.email,
      };
    },
    requestPasswordReset: () => OK,
    confirmPasswordReset: (request) => {
      if (request.token !== "demo-reset")
        throw new AuthWorkflowError("expired");
      return OK;
    },
    verifyEmail: (request) => {
      if ("token" in request) {
        if (request.token !== "demo-email")
          throw new AuthWorkflowError("expired");
        user = { ...user, emailVerified: true };
        for (const [challengeId, challenge] of challenges) {
          if (challenge.kind === "email") challenges.delete(challengeId);
        }
        synchronizeUser();
        return session ? OK : establishSession();
      }
      verifyDemoCode(request.code);
      const challenge = challenges.get(request.challengeId);
      if (!challenge || challenge.kind !== "email")
        throw new AuthWorkflowError("expired");
      user = {
        ...user,
        name: challenge.name,
        email: challenge.email,
        emailVerified: true,
      };
      challenges.delete(request.challengeId);
      synchronizeUser();
      return session ? OK : establishSession();
    },
    resendVerification: (request) => {
      if (request.challengeId) challenges.delete(request.challengeId);
      const challengeId = nextId("email-challenge");
      challenges.set(challengeId, {
        kind: "email",
        email: request.email,
        name: user.name,
      });
      return {
        kind: "verification-required",
        challengeId,
        email: request.email,
      };
    },
    getSession: () => ({
      kind: "session",
      session: session ? structuredClone(session) : null,
    }),
    logout: () => {
      session = null;
      sessions = [];
      challenges.clear();
      enrollments.clear();
      return OK;
    },
    getIdentity: () => ({ kind: "identity", identity: identity() }),
    updateProfile: (request) => {
      requireSession();
      user = { ...user, name: request.name };
      synchronizeUser();
      return OK;
    },
    changePassword: () => {
      requireSession();
      return OK;
    },
    enrollMfa: (request) => {
      requireSession();
      const enrollmentId = nextId("enrollment");
      enrollments.set(enrollmentId, { label: request.label });
      const secret = "JBSWY3DPEHPK3PXP";
      return {
        kind: "mfa-enrollment",
        enrollmentId,
        secret,
        otpauthUri: `otpauth://totp/Aureform%20demo:${encodeURIComponent(user.email)}?secret=${secret}&issuer=Aureform%20demo&digits=6&period=30`,
      };
    },
    verifyMfa: (request) => {
      verifyDemoCode(request.code, "challengeId" in request);
      if ("enrollmentId" in request) {
        requireSession();
        const enrollment = enrollments.get(request.enrollmentId);
        if (!enrollment) throw new AuthWorkflowError("expired");
        factors.push({
          id: nextId("factor"),
          type: "totp",
          label: enrollment.label,
          createdAt: now(),
        });
        enrollments.delete(request.enrollmentId);
        return OK;
      }
      const challenge = challenges.get(request.challengeId);
      if (!challenge || challenge.kind !== "mfa")
        throw new AuthWorkflowError("expired");
      challenges.delete(request.challengeId);
      user = { ...user, name: challenge.name, email: challenge.email };
      return establishSession();
    },
    revokeMfa: (request) => {
      requireSession();
      verifyDemoCode(request.code ?? "");
      const index = factors.findIndex(
        (factor) => factor.id === request.factorId,
      );
      if (index < 0) throw new AuthWorkflowError("conflict");
      factors.splice(index, 1);
      return OK;
    },
    createOrganization: (request) => {
      requireSession();
      if (
        [...organizations.values()].some(
          (entry) => entry.organization.slug === request.slug,
        )
      )
        throw new AuthWorkflowError("conflict");
      const organizationId = nextId("organization");
      organizations.set(organizationId, {
        organization: { id: organizationId, ...request, role: "owner" },
        members: [{ id: nextId("member"), user: { ...user }, role: "owner" }],
        invitations: [],
      });
      activeOrganizationId = organizationId;
      return OK;
    },
    updateOrganization: (request) => {
      const value = organizationFor(request.organizationId, true);
      if (
        [...organizations.values()].some(
          (entry) =>
            entry.organization.id !== request.organizationId &&
            entry.organization.slug === request.slug,
        )
      )
        throw new AuthWorkflowError("conflict");
      value.organization = {
        ...value.organization,
        name: request.name,
        slug: request.slug,
      };
      return OK;
    },
    switchOrganization: (request) => {
      organizationFor(request.organizationId);
      activeOrganizationId = request.organizationId;
      return OK;
    },
    deleteOrganization: (request) => {
      const value = organizationFor(request.organizationId, true);
      if (value.organization.role !== "owner")
        throw new AuthWorkflowError("forbidden");
      organizations.delete(request.organizationId);
      if (activeOrganizationId === request.organizationId)
        activeOrganizationId = organizations.keys().next().value ?? null;
      return OK;
    },
    inviteMember: (request) => {
      const value = organizationFor(request.organizationId, true);
      if (
        value.members.some((member) => member.user.email === request.email) ||
        value.invitations.some(
          (invitation) =>
            invitation.email === request.email &&
            invitation.status === "pending",
        )
      ) {
        throw new AuthWorkflowError("conflict");
      }
      value.invitations.push({
        id: nextId("invitation"),
        email: request.email,
        role: request.role,
        status: "pending",
        createdAt: now(),
        expiresAt: later(),
      });
      return OK;
    },
    revokeInvitation: (request) => {
      const value = organizationFor(request.organizationId, true);
      const invitation = value.invitations.find(
        (item) => item.id === request.invitationId && item.status === "pending",
      );
      if (!invitation) throw new AuthWorkflowError("conflict");
      invitation.status = "revoked";
      return OK;
    },
    acceptInvitation: (request) => {
      requireSession();
      if (request.token !== "demo-invitation")
        throw new AuthWorkflowError("expired");
      if (organizations.has("demo-partners"))
        throw new AuthWorkflowError("conflict");
      organizations.set("demo-partners", {
        organization: {
          id: "demo-partners",
          name: "Design Partners",
          slug: "design-partners",
          role: "member",
        },
        members: [
          {
            id: nextId("member"),
            user: {
              id: "demo-partner-owner",
              name: "Taylor Chen",
              email: "taylor@example.com",
              emailVerified: true,
            },
            role: "owner",
          },
          { id: nextId("member"), user: { ...user }, role: "member" },
        ],
        invitations: [],
      });
      activeOrganizationId = "demo-partners";
      return OK;
    },
    updateMemberRole: (request) => {
      const value = organizationFor(request.organizationId, true);
      const member = value.members.find((item) => item.id === request.memberId);
      if (!member || member.role === "owner" || member.user.id === user.id)
        throw new AuthWorkflowError("forbidden");
      member.role = request.role;
      return OK;
    },
    removeMember: (request) => {
      const value = organizationFor(request.organizationId, true);
      const member = value.members.find((item) => item.id === request.memberId);
      if (!member || member.role === "owner" || member.user.id === user.id)
        throw new AuthWorkflowError("forbidden");
      value.members = value.members.filter(
        (item) => item.id !== request.memberId,
      );
      return OK;
    },
    revokeSession: (request) => {
      requireSession();
      const value = sessions.find((item) => item.id === request.sessionId);
      if (!value) throw new AuthWorkflowError("conflict");
      if (value.current) {
        session = null;
        sessions = [];
        challenges.clear();
        enrollments.clear();
      } else
        sessions = sessions.filter((item) => item.id !== request.sessionId);
      return OK;
    },
    revokeOtherSessions: () => {
      requireSession();
      sessions = sessions.filter((item) => item.current);
      return OK;
    },
  };
  const delayed = {} as Record<
    AuthWorkflowOperation,
    (
      request: AuthWorkflowRequests[AuthWorkflowOperation],
      scope: AuthWorkflowScope,
    ) => unknown | Promise<unknown>
  >;
  for (const operation of Object.keys(handlers) as AuthWorkflowOperation[]) {
    delayed[operation] = async (request, scope) => {
      await new Promise<void>((resolve, reject) => {
        checkAbort(scope.signal);
        const onAbort = () => {
          clearTimeout(timer);
          scope.signal?.removeEventListener("abort", onAbort);
          reject(new AuthWorkflowError("aborted"));
        };
        const timer = setTimeout(() => {
          scope.signal?.removeEventListener("abort", onAbort);
          resolve();
        }, delayMs);
        scope.signal?.addEventListener("abort", onAbort, { once: true });
      });
      checkAbort(scope.signal);
      return await handlers[operation](request as never, scope);
    };
  }
  return makeAdapter("demo", providerId, delayed);
}

import {
  CommerceError,
  commerceProductSchema,
  commerceSnapshotSchema,
  type CommerceAction,
  type CommerceBilling,
  type CommerceProduct,
  type CommerceSnapshot,
} from "./commerce";

export const COMMERCE_STORAGE_PREFIX = "aureform:commerce:v1:";
export const commercePlans = [
  { name: "Starter", amount: 9900 },
  { name: "Pro", amount: 24900 },
  { name: "Enterprise", amount: 69900 },
] as const;

export function parseCommerceSnapshot(value: unknown): CommerceSnapshot | null {
  const parsed = commerceSnapshotSchema.safeParse(value);
  if (!parsed.success) return null;
  const snapshot = parsed.data;
  for (const records of [
    snapshot.products,
    snapshot.orders,
    snapshot.invoices,
  ]) {
    if (new Set(records.map((item) => item.id)).size !== records.length)
      return null;
  }
  if (
    new Set(snapshot.products.map((item) => item.sku.toLowerCase())).size !==
    snapshot.products.length
  )
    return null;
  if (
    snapshot.products.some(
      (item) =>
        new Set(item.images.map((image) => image.id)).size !==
        item.images.length,
    )
  )
    return null;
  if (
    snapshot.orders.some(
      (order) =>
        order.total !==
        order.items.reduce(
          (sum, item) => sum + item.unitAmount * item.quantity,
          0,
        ),
    )
  )
    return null;
  return snapshot;
}

/** A changed amount/currency needs a new Stripe Price; never reuse the old id. */
export function upsertCommerceProduct(
  snapshot: CommerceSnapshot,
  candidate: CommerceProduct,
  now: string,
): CommerceSnapshot {
  const validated = commerceProductSchema.safeParse(candidate);
  if (!validated.success)
    throw new CommerceError("validation", "Check the product fields.");
  const product = validated.data;
  if (
    snapshot.products.some(
      (item) =>
        item.id !== product.id &&
        item.sku.toLowerCase() === product.sku.toLowerCase(),
    )
  ) {
    throw new CommerceError(
      "conflict",
      "Another product already uses this SKU.",
    );
  }
  const previous = snapshot.products.find((item) => item.id === product.id);
  if (!previous && snapshot.products.length >= 500) {
    throw new CommerceError("conflict", "The demo catalog is full.");
  }
  const changedPrice =
    previous &&
    (previous.unitAmount !== product.unitAmount ||
      previous.currency !== product.currency);
  const { stripePriceId, ...fields } = product;
  const next: CommerceProduct = {
    ...fields,
    ...(stripePriceId &&
    (!changedPrice || stripePriceId !== previous?.stripePriceId)
      ? { stripePriceId }
      : {}),
    updatedAt: now,
  };
  return {
    ...snapshot,
    products: previous
      ? snapshot.products.map((item) => (item.id === next.id ? next : item))
      : [next, ...snapshot.products],
  };
}

/** Applies a demo payment once. Failed payments never consume stock. */
export function completeMockCheckout(
  snapshot: CommerceSnapshot,
  action: Extract<CommerceAction, { mode: "mock" }>,
  outcome: "paid" | "failed",
  now: string,
): CommerceSnapshot {
  if (action.kind === "portal") {
    throw new CommerceError(
      "validation",
      "The customer portal does not accept a payment.",
    );
  }
  if (action.kind === "order") {
    const order = snapshot.orders.find((item) => item.id === action.id);
    if (
      !order ||
      order.status === "cancelled" ||
      order.paymentStatus === "refunded"
    ) {
      throw new CommerceError("unavailable", "This order cannot be paid.");
    }
    if (order.paymentStatus === "paid") return snapshot;
    if (outcome === "failed")
      return {
        ...snapshot,
        orders: snapshot.orders.map((item) =>
          item.id === order.id ? { ...item, paymentStatus: "failed" } : item,
        ),
      };
    const quantities = new Map<string, number>();
    for (const line of order.items) {
      quantities.set(
        line.productId,
        (quantities.get(line.productId) ?? 0) + line.quantity,
      );
    }
    for (const [productId, quantity] of quantities) {
      const product = snapshot.products.find((item) => item.id === productId);
      if (
        !product ||
        product.status !== "active" ||
        product.inventory < quantity
      ) {
        throw new CommerceError(
          "conflict",
          "Inventory changed. Review the order before paying.",
        );
      }
    }
    const invoiceId = `inv-order-${order.id}`;
    return {
      ...snapshot,
      products: snapshot.products.map((product) => ({
        ...product,
        inventory: product.inventory - (quantities.get(product.id) ?? 0),
      })),
      orders: snapshot.orders.map((item) =>
        item.id === order.id ? { ...item, paymentStatus: "paid" } : item,
      ),
      invoices: snapshot.invoices.some((item) => item.id === invoiceId)
        ? snapshot.invoices
        : [
            {
              id: invoiceId,
              number: `INV-${order.number.replace("#", "")}`,
              customerName: order.customerName,
              customerEmail: order.customerEmail,
              description: `Order ${order.number}`,
              amount: order.total,
              currency: order.currency,
              status: "paid",
              issuedAt: now,
              dueAt: now,
            },
            ...snapshot.invoices,
          ],
    };
  }
  if (action.kind === "invoice") {
    const invoice = snapshot.invoices.find((item) => item.id === action.id);
    if (!invoice || invoice.status === "draft" || invoice.status === "void") {
      throw new CommerceError("unavailable", "This invoice cannot be paid.");
    }
    if (invoice.status === "paid" || outcome === "failed") return snapshot;
    return {
      ...snapshot,
      invoices: snapshot.invoices.map((item) =>
        item.id === invoice.id ? { ...item, status: "paid" } : item,
      ),
    };
  }
  const plan = commercePlans.find((item) => item.name === action.id);
  if (!plan) throw new CommerceError("validation", "Choose an available plan.");
  if (outcome === "failed") return snapshot;
  if (
    snapshot.billing.plan === plan.name &&
    snapshot.billing.status === "active"
  )
    return snapshot;
  const period = new Date(now);
  period.setUTCMonth(period.getUTCMonth() + 1);
  const billing: CommerceBilling = {
    ...snapshot.billing,
    plan: plan.name,
    amount: plan.amount,
    status: "active",
    interval: "month",
    currentPeriodEnd: period.toISOString(),
  };
  return {
    ...snapshot,
    billing,
    invoices: [
      {
        id: `inv-plan-${plan.name.toLowerCase()}-${Date.parse(now)}`,
        number: `SUB-${Date.parse(now).toString(36).toUpperCase()}`,
        customerName: "Aureform workspace",
        customerEmail: billing.customerEmail,
        description: `${plan.name} subscription`,
        amount: plan.amount,
        currency: billing.currency,
        status: "paid",
        issuedAt: now,
        dueAt: now,
      },
      ...snapshot.invoices,
    ],
  };
}

import { z } from "zod";

export const commerceCurrencies = ["usd", "eur", "gbp"] as const;
export type CommerceCurrency = (typeof commerceCurrencies)[number];
export type ProductStatus = "active" | "draft" | "archived";
export type ProductImage = {
  id: string;
  src: string;
  alt: string;
  width?: number;
  height?: number;
};
/** Amounts are integer minor units. The supported currencies use two decimals. */
export type CommerceProduct = {
  id: string;
  name: string;
  sku: string;
  description: string;
  category: string;
  status: ProductStatus;
  unitAmount: number;
  currency: CommerceCurrency;
  inventory: number;
  images: ProductImage[];
  tags: string[];
  /** Optional display references; the backend owns the actual provider mapping. */
  providerProductId?: string;
  providerPriceId?: string;
  stripeProductId?: string;
  stripePriceId?: string;
  updatedAt: string;
};
export type OrderLine = {
  productId: string;
  name: string;
  quantity: number;
  unitAmount: number;
  image?: string;
};
export type CommerceOrder = {
  id: string;
  number: string;
  customerName: string;
  customerEmail: string;
  currency: CommerceCurrency;
  total: number;
  status: "processing" | "shipped" | "delivered" | "cancelled";
  paymentStatus: "unpaid" | "paid" | "failed" | "refunded";
  items: OrderLine[];
  createdAt: string;
  shippingAddress: string;
  providerSessionId?: string;
  stripeSessionId?: string;
};
export type CommerceInvoice = {
  id: string;
  number: string;
  customerName: string;
  customerEmail: string;
  description: string;
  amount: number;
  currency: CommerceCurrency;
  status: "draft" | "open" | "paid" | "overdue" | "void";
  issuedAt: string;
  dueAt: string;
  providerInvoiceId?: string;
  stripeInvoiceId?: string;
};
export type CommerceBilling = {
  plan: "Starter" | "Pro" | "Enterprise";
  status: "active" | "trialing" | "past_due" | "cancelled";
  amount: number;
  currency: CommerceCurrency;
  interval: "month" | "year";
  currentPeriodEnd: string;
  cardBrand: string;
  /** Empty when the provider does not expose card details. */
  cardLast4: string;
  customerEmail: string;
  providerCustomerId?: string;
  stripeCustomerId?: string;
};
export type CommerceSnapshot = {
  version: 1;
  products: CommerceProduct[];
  orders: CommerceOrder[];
  invoices: CommerceInvoice[];
  billing: CommerceBilling;
};
export type NewOrderInput = {
  customerName: string;
  customerEmail: string;
  shippingAddress?: string;
  items: { productId: string; quantity: number }[];
};
export type NewInvoiceInput = {
  customerName: string;
  customerEmail: string;
  description: string;
  amount: number;
  currency: CommerceCurrency;
  dueAt: string;
};
export type CheckoutRequest = {
  kind: "order" | "invoice" | "subscription";
  id: string;
};
export type CommerceAction =
  | { mode: "mock"; kind: CheckoutRequest["kind"] | "portal"; id: string }
  | { mode: "redirect"; url: string };
export type CommerceScope = { workspaceId: string; signal?: AbortSignal };
export type CommerceProviderIdentity = { id: string; label: string };

/** Implement this contract on your own authenticated backend. */
export type CommerceAdapter = {
  mode: "stripe" | "provider";
  /** Legacy Stripe adapters can omit these fields and retain their old policy. */
  provider?: CommerceProviderIdentity;
  /** Required for provider mode; exact HTTPS origins, with no wildcard hosts. */
  trustedRedirectOrigins?: readonly string[];
  load: (scope: CommerceScope) => Promise<CommerceSnapshot>;
  saveProduct: (
    product: CommerceProduct,
    scope: CommerceScope,
  ) => Promise<CommerceProduct>;
  archiveProduct: (
    productId: string,
    scope: CommerceScope,
  ) => Promise<CommerceProduct>;
  syncProduct: (
    productId: string,
    scope: CommerceScope,
  ) => Promise<CommerceProduct>;
  createOrder: (
    input: NewOrderInput,
    scope: CommerceScope,
  ) => Promise<CommerceOrder>;
  updateOrderStatus: (
    orderId: string,
    status: CommerceOrder["status"],
    scope: CommerceScope,
  ) => Promise<CommerceOrder>;
  createInvoice: (
    input: NewInvoiceInput,
    scope: CommerceScope,
  ) => Promise<CommerceInvoice>;
  checkout: (
    input: CheckoutRequest,
    scope: CommerceScope,
  ) => Promise<CommerceAction>;
  portal: (scope: CommerceScope) => Promise<CommerceAction>;
};

export type CommerceContextValue = CommerceSnapshot & {
  ready: boolean;
  busy: string | null;
  mode: "mock" | CommerceAdapter["mode"];
  provider?: CommerceProviderIdentity;
  error: CommerceError | null;
  persistenceError: "read" | "write" | "invalid" | null;
  canWrite: boolean;
  canManageBilling: boolean;
  reload: () => Promise<void>;
  retryPersistence: () => void;
  saveProduct: (product: CommerceProduct) => Promise<CommerceProduct>;
  archiveProduct: (id: string) => Promise<CommerceProduct>;
  syncProduct: (id: string) => Promise<CommerceProduct>;
  createOrder: (input: NewOrderInput) => Promise<CommerceOrder>;
  updateOrderStatus: (
    id: string,
    status: CommerceOrder["status"],
  ) => Promise<CommerceOrder>;
  createInvoice: (input: NewInvoiceInput) => Promise<CommerceInvoice>;
  checkoutOrder: (id: string) => Promise<CommerceAction>;
  payInvoice: (id: string) => Promise<CommerceAction>;
  checkoutPlan: (plan: CommerceBilling["plan"]) => Promise<CommerceAction>;
  openPortal: () => Promise<CommerceAction>;
  simulateCheckout: (
    action: Extract<CommerceAction, { mode: "mock" }>,
    outcome: "paid" | "failed",
  ) => Promise<void>;
};

/** Shared by connected views; legacy Stripe contexts keep their display name. */
export function getCommerceProviderLabel(
  value: Pick<CommerceContextValue, "mode" | "provider">,
) {
  return (
    value.provider?.label ??
    (value.mode === "mock"
      ? "Demo"
      : value.mode === "stripe"
        ? "Stripe"
        : "Commerce")
  );
}

const integerAmount = z.number().int().nonnegative().max(100_000_000);
const identifier = z.string().trim().min(1).max(100);
const currency = z.enum(commerceCurrencies);
export function isProductImageSource(src: string) {
  if (src.startsWith("/") && !src.startsWith("//") && !src.includes("\\")) {
    return !src.includes("..");
  }
  if (/^data:image\/(?:jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(src)) {
    return src.length <= 1_000_000;
  }
  try {
    return new URL(src).protocol === "https:";
  } catch {
    return false;
  }
}
export const productImageSchema = z.object({
  id: identifier,
  src: z
    .string()
    .refine(isProductImageSource, "Use a local, HTTPS or prepared image."),
  alt: z.string().trim().min(1).max(240),
  width: z.number().int().positive().max(16384).optional(),
  height: z.number().int().positive().max(16384).optional(),
});
export const commerceProductSchema = z.object({
  id: identifier,
  name: z.string().trim().min(2).max(140),
  sku: z.string().trim().min(2).max(64),
  description: z.string().trim().max(5000),
  category: z.string().trim().min(1).max(80),
  status: z.enum(["active", "draft", "archived"]),
  unitAmount: integerAmount,
  currency,
  inventory: z.number().int().nonnegative().max(1_000_000),
  images: z.array(productImageSchema).max(6),
  tags: z.array(z.string().trim().min(1).max(40)).max(12),
  providerProductId: identifier.optional(),
  providerPriceId: identifier.optional(),
  stripeProductId: identifier.optional(),
  stripePriceId: identifier.optional(),
  updatedAt: z.iso.datetime(),
});
const orderLineSchema = z.object({
  productId: identifier,
  name: z.string().min(1).max(140),
  quantity: z.number().int().min(1).max(999),
  unitAmount: integerAmount,
  image: z.string().refine(isProductImageSource).optional(),
});
export const commerceOrderSchema = z.object({
  id: identifier,
  number: z.string().min(1).max(40),
  customerName: z.string().trim().min(2).max(140),
  customerEmail: z.email(),
  currency,
