    item: IntegrationDefinition,
    permissions: string[],
    resourceIds: string[],
  ) {
    validateIntegrationSelection(item, permissions, resourceIds);
    if (
      resourceIds.some(
        (id) =>
          !Array.from(
            { length: 12 },
            (_, index) => `${item.id}-resource-${index + 1}`,
          ).includes(id),
      )
